insert into public.courses values ('arithmetic','{"id":"arithmetic","title":"Everyday arithmetic","subject":"Arithmetic","grades":[0,1,2,3,4,5],"description":"Build confidence with numbers, one small discovery at a time.","units":[{"id":"counting","title":"Counting to ten","grades":[0],"requires":[],"x":0,"y":0,"lessons":[{"id":"counting-practice","title":"Counting to ten","explanation":"Count each object once. The last number tells you how many.","example":"● ● ● means 3 objects.","questions":[{"id":"counting-q1","prompt":"How many stars? ★ ★ ★ ★","answer":"4","hint":"Count each object once. The last number tells you how many.","explanation":"Count 1, 2, 3, 4. There are 4 stars.","kind":"numeric","difficulty":"easy"},{"id":"counting-q2","prompt":"What number comes just after 6?","answer":"7","hint":"Count each object once. The last number tells you how many.","explanation":"Count forward: 5, 6, 7.","kind":"numeric","difficulty":"easy"}]}]},{"id":"add-twenty","title":"Adding within twenty","grades":[1],"requires":["counting"],"x":260,"y":0,"lessons":[{"id":"add-twenty-practice","title":"Adding within twenty","explanation":"Start with one number and count forward to add the other.","example":"5 + 3 = 8.","questions":[{"id":"add-twenty-q1","prompt":"What is 6 + 2?","answer":"8","hint":"Start with one number and count forward to add the other.","explanation":"Count two more after 6: 7, 8.","kind":"numeric","difficulty":"easy"},{"id":"add-twenty-q2","prompt":"What is 9 + 5?","answer":"14","hint":"Start with one number and count forward to add the other.","explanation":"9 + 1 makes 10, then add the remaining 4 to get 14.","kind":"numeric","difficulty":"easy"}]}]},{"id":"place-value","title":"Tens and ones","grades":[2],"requires":["add-twenty"],"x":520,"y":0,"lessons":[{"id":"place-value-practice","title":"Tens and ones","explanation":"A two-digit number is made of tens and ones.","example":"42 has 4 tens and 2 ones.","questions":[{"id":"place-value-q1","prompt":"How many tens are in 73?","answer":"7","hint":"A two-digit number is made of tens and ones.","explanation":"73 is 7 tens and 3 ones.","kind":"numeric","difficulty":"easy"},{"id":"place-value-q2","prompt":"What number has 5 tens and 8 ones?","answer":"58","hint":"A two-digit number is made of tens and ones.","explanation":"50 + 8 = 58.","kind":"numeric","difficulty":"easy"}]}]},{"id":"addition","title":"Addition","x":0,"y":200,"requires":[],"lessons":[{"id":"addition","title":"Adding with confidence","explanation":"Addition combines quantities. You can split a number to make a friendly ten.","example":"8 + 5 = 8 + 2 + 3 = 13.","questions":[{"id":"a1","prompt":"What is 7 + 6?","answer":"13","hint":"Make ten: 7 + 3 + 3.","explanation":"7 + 3 = 10; 10 + 3 = 13.","kind":"numeric","difficulty":"easy"},{"id":"a2","prompt":"What is 28 + 15?","answer":"43","hint":"Add tens, then ones.","explanation":"28 + 10 = 38; 38 + 5 = 43.","kind":"numeric","difficulty":"easy"}]}],"grades":[2]},{"id":"multiply","title":"Multiplication","x":260,"y":200,"requires":["addition"],"lessons":[{"id":"multiply","title":"Equal groups","explanation":"Multiplication counts equal groups.","example":"4 groups of 3 make 4 × 3 = 12.","questions":[{"id":"m1","prompt":"Five bags each have 4 apples. How many apples?","answer":"20","hint":"Add four five times.","explanation":"5 × 4 = 20 apples.","kind":"numeric","difficulty":"easy"},{"id":"m2","prompt":"What is 6 × 7?","answer":"42","hint":"Use 5 × 7 + 7.","explanation":"35 + 7 = 42.","kind":"numeric","difficulty":"easy"}]}],"grades":[3]},{"id":"division","title":"Sharing equally","grades":[3],"requires":["multiply"],"x":520,"y":200,"lessons":[{"id":"division-practice","title":"Sharing equally","explanation":"Division splits a total into equal groups.","example":"12 shared among 3 groups gives 4 in each group.","questions":[{"id":"division-q1","prompt":"18 apples are shared equally among 3 baskets. How many per basket?","answer":"6","hint":"Division splits a total into equal groups.","explanation":"18 ÷ 3 = 6 because 3 × 6 = 18.","kind":"numeric","difficulty":"easy"},{"id":"division-q2","prompt":"What is 32 ÷ 4?","answer":"8","hint":"Division splits a total into equal groups.","explanation":"4 × 8 = 32, so 32 ÷ 4 = 8.","kind":"numeric","difficulty":"easy"}]}]},{"id":"multi-digit","title":"Larger multiplication","grades":[4],"requires":["multiply"],"x":0,"y":400,"lessons":[{"id":"multi-digit-practice","title":"Larger multiplication","explanation":"Split a number into tens and ones, multiply each part, then add.","example":"23 × 3 = 20 × 3 + 3 × 3 = 69.","questions":[{"id":"multi-digit-q1","prompt":"What is 24 × 3?","answer":"72","hint":"Split a number into tens and ones, multiply each part, then add.","explanation":"20 × 3 + 4 × 3 = 60 + 12 = 72.","kind":"numeric","difficulty":"easy"},{"id":"multi-digit-q2","prompt":"What is 16 × 5?","answer":"80","hint":"Split a number into tens and ones, multiply each part, then add.","explanation":"10 × 5 + 6 × 5 = 50 + 30 = 80.","kind":"numeric","difficulty":"easy"}]}]},{"id":"decimal-arithmetic","title":"Adding decimals","grades":[5],"requires":[],"x":260,"y":400,"lessons":[{"id":"decimal-arithmetic-practice","title":"Adding decimals","explanation":"Line up the decimal points so the same place values are added.","example":"1.25 + 0.40 = 1.65.","questions":[{"id":"decimal-arithmetic-q1","prompt":"What is 2.35 + 1.4?","answer":"3.75","hint":"Line up the decimal points so the same place values are added.","explanation":"2.35 + 1.40 = 3.75.","kind":"numeric","difficulty":"easy"},{"id":"decimal-arithmetic-q2","prompt":"What is 5.6 − 2.75?","answer":"2.85","hint":"Line up the decimal points so the same place values are added.","explanation":"5.60 − 2.75 = 2.85.","kind":"numeric","difficulty":"easy"}]}]},{"id":"path-g0-count-stars","title":"Count the stars","grades":[0],"requires":[],"lessons":[{"id":"g0-count-stars","title":"Count the stars","explanation":"Touch each star once as you count. The last number tells you how many.","example":"Count slowly: ★ ★ ★. One, two, three. There are 3 stars.","questions":[{"id":"g0-count-stars-q1","prompt":"How many stars do you see?","answer":"3","hint":"Point to each star once.","explanation":"Count 1, 2, 3. There are 3 stars.","visual":{"type":"objects","count":3},"kind":"numeric","difficulty":"easy"},{"id":"g0-count-stars-q2","prompt":"How many stars are in this group?","answer":"5","hint":"Start at the left. Count every star once.","explanation":"Count 1, 2, 3, 4, 5. There are 5 stars.","visual":{"type":"objects","count":5},"kind":"numeric","difficulty":"medium"},{"id":"g0-count-stars-q3","prompt":"Count all the stars. How many are there?","answer":"8","hint":"Count the top row, then keep counting on the next row.","explanation":"There are 5 on the top row and 3 below: 8 stars.","visual":{"type":"objects","count":8},"kind":"numeric","difficulty":"medium"}]}],"x":520,"y":400},{"id":"path-g0-one-more","title":"One more, one less","grades":[0],"requires":["path-g0-count-stars"],"lessons":[{"id":"g0-one-more","title":"One more, one less","explanation":"One more is the next counting number. One less is the number just before.","example":"One more than 3 is 4. One less than 3 is 2.","questions":[{"id":"g0-one-more-q1","prompt":"What is one more than 2?","answer":"3","hint":"Count forward one step from 2.","explanation":"2, then 3. One more than 2 is 3.","kind":"numeric","difficulty":"easy"},{"id":"g0-one-more-q2","prompt":"What is one less than 5?","answer":"4","hint":"Count back one step from 5.","explanation":"5, then 4. One less than 5 is 4.","kind":"numeric","difficulty":"medium"},{"id":"g0-one-more-q3","prompt":"You have 6 blocks and get 1 more. How many blocks now?","answer":"7","hint":"Start at 6 and count one more.","explanation":"6 + 1 = 7 blocks.","kind":"numeric","difficulty":"medium"}]}],"x":0,"y":600},{"id":"path-g1-make-ten","title":"Make ten","grades":[1],"requires":[],"lessons":[{"id":"g1-make-ten","title":"Make ten","explanation":"Number partners can join to make 10. Count on to find the missing partner.","example":"7 and 3 make 10 because 7 + 3 = 10.","questions":[{"id":"g1-make-ten-q1","prompt":"4 + what number = 10?","answer":"6","hint":"Count from 4 up to 10.","explanation":"4 + 6 = 10. The missing partner is 6.","kind":"numeric","difficulty":"easy"},{"id":"g1-make-ten-q2","prompt":"8 + what number = 10?","answer":"2","hint":"How many more after 8 reach 10?","explanation":"9, 10: two more. 8 + 2 = 10.","kind":"numeric","difficulty":"medium"},{"id":"g1-make-ten-q3","prompt":"There are 3 red beads and some blue beads. There are 10 beads altogether. How many are blue?","answer":"7","hint":"Find the partner that joins 3 to make 10.","explanation":"10 − 3 = 7 blue beads.","kind":"numeric","difficulty":"medium"}]}],"x":260,"y":600},{"id":"path-g1-take-away","title":"Taking away within twenty","grades":[1],"requires":["path-g1-make-ten"],"lessons":[{"id":"g1-take-away","title":"Taking away within twenty","explanation":"Subtraction tells how many are left. Start with the total and take away the smaller amount.","example":"12 − 3 = 9. Count back 3 steps: 11, 10, 9.","questions":[{"id":"g1-take-away-q1","prompt":"What is 9 − 4?","answer":"5","hint":"Start at 9 and count back 4 steps.","explanation":"8, 7, 6, 5. So 9 − 4 = 5.","kind":"numeric","difficulty":"easy"},{"id":"g1-take-away-q2","prompt":"What is 15 − 5?","answer":"10","hint":"Take 5 ones away from 15.","explanation":"15 − 5 = 10.","kind":"numeric","difficulty":"medium"},{"id":"g1-take-away-q3","prompt":"A basket holds 14 apples. You give away 6. How many are left?","answer":"8","hint":"Take away 4 to reach 10, then take away 2 more.","explanation":"14 − 4 = 10, and 10 − 2 = 8 apples.","kind":"numeric","difficulty":"medium"}]}],"x":520,"y":600},{"id":"path-g2-skip-count","title":"Skip-counting patterns","grades":[2],"requires":[],"lessons":[{"id":"g2-skip-count","title":"Skip-counting patterns","explanation":"Skip-counting adds the same amount each time. Look at the gap between neighboring numbers.","example":"Counting by fives: 5, 10, 15, 20. Each jump adds 5.","questions":[{"id":"g2-skip-count-q1","prompt":"What comes next: 2, 4, 6, 8, __?","answer":"10","hint":"Each jump adds 2.","explanation":"8 + 2 = 10.","kind":"numeric","difficulty":"easy"},{"id":"g2-skip-count-q2","prompt":"What comes next: 5, 10, 15, __?","answer":"20","hint":"Keep counting by fives.","explanation":"15 + 5 = 20.","kind":"numeric","difficulty":"medium"},{"id":"g2-skip-count-q3","prompt":"What comes next: 20, 30, 40, __?","answer":"50","hint":"Each jump adds one ten.","explanation":"40 + 10 = 50.","kind":"numeric","difficulty":"medium"}]}],"x":0,"y":800},{"id":"path-g2-two-digit-sums","title":"Adding tens and ones","grades":[2],"requires":["path-g2-skip-count"],"lessons":[{"id":"g2-two-digit-sums","title":"Adding tens and ones","explanation":"Add tens to tens and ones to ones. Ten ones can regroup into one ten.","example":"24 + 13 = (20 + 10) + (4 + 3) = 30 + 7 = 37.","questions":[{"id":"g2-two-digit-sums-q1","prompt":"What is 32 + 25?","answer":"57","hint":"Add 30 + 20 and 2 + 5.","explanation":"50 + 7 = 57.","kind":"numeric","difficulty":"easy"},{"id":"g2-two-digit-sums-q2","prompt":"What is 47 + 16?","answer":"63","hint":"7 + 6 makes 13 ones: one extra ten and 3 ones.","explanation":"40 + 10 + 13 = 63.","kind":"numeric","difficulty":"medium"},{"id":"g2-two-digit-sums-q3","prompt":"You collect 28 shells and then 35 more. How many shells altogether?","answer":"63","hint":"Add the tens, then regroup 8 + 5 ones.","explanation":"20 + 30 + 8 + 5 = 50 + 13 = 63 shells.","kind":"numeric","difficulty":"medium"}]}],"x":260,"y":800},{"id":"path-g3-arrays","title":"Rows and columns","grades":[3],"requires":[],"lessons":[{"id":"g3-arrays","title":"Rows and columns","explanation":"An array has equal rows. Multiply the number of rows by the number in each row.","example":"Three rows of four counters make 3 × 4 = 12 counters.","questions":[{"id":"g3-arrays-q1","prompt":"There are 3 rows with 4 counters in each row. How many counters?","answer":"12","hint":"Add 4 three times, or multiply 3 × 4.","explanation":"4 + 4 + 4 = 12.","visual":{"type":"array","rows":3,"columns":4},"kind":"numeric","difficulty":"easy"},{"id":"g3-arrays-q2","prompt":"There are 4 rows with 5 counters in each row. How many counters?","answer":"20","hint":"Each row adds 5 counters.","explanation":"4 × 5 = 20 counters.","visual":{"type":"array","rows":4,"columns":5},"kind":"numeric","difficulty":"medium"},{"id":"g3-arrays-q3","prompt":"A garden has 6 rows with 3 flowers in each row. How many flowers?","answer":"18","hint":"There are 6 equal groups of 3.","explanation":"6 × 3 = 18 flowers.","visual":{"type":"array","rows":6,"columns":3},"kind":"numeric","difficulty":"medium"}]}],"x":520,"y":800},{"id":"path-g3-division-facts","title":"Find the missing group","grades":[3],"requires":["path-g3-arrays"],"lessons":[{"id":"g3-division-facts","title":"Find the missing group","explanation":"Multiplication and division are partners. Use a multiplication fact to find a missing group size.","example":"24 ÷ 6 asks: 6 times what makes 24? Since 6 × 4 = 24, the answer is 4.","questions":[{"id":"g3-division-facts-q1","prompt":"What is 21 ÷ 3?","answer":"7","hint":"3 times what makes 21?","explanation":"3 × 7 = 21, so 21 ÷ 3 = 7.","kind":"numeric","difficulty":"easy"},{"id":"g3-division-facts-q2","prompt":"What is 56 ÷ 7?","answer":"8","hint":"Use the 7-times table.","explanation":"7 × 8 = 56, so 56 ÷ 7 = 8.","kind":"numeric","difficulty":"medium"},{"id":"g3-division-facts-q3","prompt":"36 stickers are shared equally among 4 friends. How many does each friend get?","answer":"9","hint":"Find the number that makes 4 equal groups total 36.","explanation":"4 × 9 = 36. Each friend gets 9 stickers.","kind":"numeric","difficulty":"medium"}]}],"x":0,"y":1000},{"id":"path-g4-factors","title":"Find the factors","grades":[4],"requires":[],"lessons":[{"id":"g4-factors","title":"Find the factors","explanation":"A factor divides a whole number without a remainder. Factor pairs multiply to make the number.","example":"The factor pairs of 12 are 1 × 12, 2 × 6 and 3 × 4.","questions":[{"id":"g4-factors-q1","prompt":"4 × what whole number = 28?","answer":"7","hint":"Find the partner of 4 in a factor pair of 28.","explanation":"28 ÷ 4 = 7, so 4 × 7 = 28.","kind":"numeric","difficulty":"easy"},{"id":"g4-factors-q2","prompt":"How many positive whole-number factors does 12 have?","answer":"6","hint":"List both numbers from each factor pair, without repeats.","explanation":"The factors are 1, 2, 3, 4, 6 and 12: six factors.","kind":"numeric","difficulty":"medium"},{"id":"g4-factors-q3","prompt":"What is the greatest common factor of 18 and 24?","answer":"6","hint":"List factors shared by both numbers, then choose the greatest.","explanation":"Their common factors are 1, 2, 3 and 6. The greatest is 6.","kind":"numeric","difficulty":"medium"}]}],"x":260,"y":1000},{"id":"path-g5-decimal-products","title":"Multiplying decimals","grades":[5],"requires":[],"lessons":[{"id":"g5-decimal-products","title":"Multiplying decimals","explanation":"Multiply as whole numbers, then place the decimal using the total number of decimal places in the factors. Estimate to check the size.","example":"1.2 × 0.3: 12 × 3 = 36. There are two decimal places altogether, so the product is 0.36.","questions":[{"id":"g5-decimal-products-q1","prompt":"What is 0.4 × 0.5?","answer":"0.2","hint":"4 × 5 = 20. Use two decimal places.","explanation":"0.4 × 0.5 = 0.20 = 0.2.","kind":"numeric","difficulty":"easy"},{"id":"g5-decimal-products-q2","prompt":"What is 2.5 × 1.2?","answer":"3","hint":"25 × 12 = 300. Use two decimal places.","explanation":"300 hundredths = 3.00 = 3.","kind":"numeric","difficulty":"medium"},{"id":"g5-decimal-products-q3","prompt":"Three meters of ribbon cost $1.75 per meter. How many dollars is the total cost?","answer":"5.25","hint":"Multiply the price per meter by 3.","explanation":"1.75 × 3 = 5.25 dollars.","kind":"numeric","difficulty":"medium"}]}],"x":520,"y":1000}],"planned":false}') on conflict(id) do update set content=excluded.content;
