insert into public.units values ('multi-digit','arithmetic','{"id":"multi-digit","title":"Larger multiplication","grades":[4],"requires":["multiply"],"x":0,"y":400,"lessons":[{"id":"multi-digit-practice","title":"Larger multiplication","explanation":"Split a number into tens and ones, multiply each part, then add.","example":"23 × 3 = 20 × 3 + 3 × 3 = 69.","questions":[{"id":"multi-digit-q1","prompt":"What is 24 × 3?","answer":"72","hint":"Split a number into tens and ones, multiply each part, then add.","explanation":"20 × 3 + 4 × 3 = 60 + 12 = 72.","kind":"numeric","difficulty":"easy"},{"id":"multi-digit-q2","prompt":"What is 16 × 5?","answer":"80","hint":"Split a number into tens and ones, multiply each part, then add.","explanation":"10 × 5 + 6 × 5 = 50 + 30 = 80.","kind":"numeric","difficulty":"easy"}]}]}') on conflict(id) do update set content=excluded.content;
