insert into public.units values ('decimal-arithmetic','arithmetic','{"id":"decimal-arithmetic","title":"Adding decimals","grades":[5],"requires":[],"x":260,"y":400,"lessons":[{"id":"decimal-arithmetic-practice","title":"Adding decimals","explanation":"Line up the decimal points so the same place values are added.","example":"1.25 + 0.40 = 1.65.","questions":[{"id":"decimal-arithmetic-q1","prompt":"What is 2.35 + 1.4?","answer":"3.75","hint":"Line up the decimal points so the same place values are added.","explanation":"2.35 + 1.40 = 3.75.","kind":"numeric","difficulty":"easy"},{"id":"decimal-arithmetic-q2","prompt":"What is 5.6 − 2.75?","answer":"2.85","hint":"Line up the decimal points so the same place values are added.","explanation":"5.60 − 2.75 = 2.85.","kind":"numeric","difficulty":"easy"}]}]}') on conflict(id) do update set content=excluded.content;
