insert into public.units values ('path-g0-count-stars','arithmetic','{"id":"path-g0-count-stars","title":"Count the stars","grades":[0],"requires":[],"lessons":[{"id":"g0-count-stars","title":"Count the stars","explanation":"Touch each star once as you count. The last number tells you how many.","example":"Count slowly: ★ ★ ★. One, two, three. There are 3 stars.","questions":[{"id":"g0-count-stars-q1","prompt":"How many stars do you see?","answer":"3","hint":"Point to each star once.","explanation":"Count 1, 2, 3. There are 3 stars.","visual":{"type":"objects","count":3},"kind":"numeric","difficulty":"easy"},{"id":"g0-count-stars-q2","prompt":"How many stars are in this group?","answer":"5","hint":"Start at the left. Count every star once.","explanation":"Count 1, 2, 3, 4, 5. There are 5 stars.","visual":{"type":"objects","count":5},"kind":"numeric","difficulty":"medium"},{"id":"g0-count-stars-q3","prompt":"Count all the stars. How many are there?","answer":"8","hint":"Count the top row, then keep counting on the next row.","explanation":"There are 5 on the top row and 3 below: 8 stars.","visual":{"type":"objects","count":8},"kind":"numeric","difficulty":"medium"}]}],"x":520,"y":400}') on conflict(id) do update set content=excluded.content;
