insert into public.units values ('path-g0-one-more','arithmetic','{"id":"path-g0-one-more","title":"One more, one less","grades":[0],"requires":["path-g0-count-stars"],"lessons":[{"id":"g0-one-more","title":"One more, one less","explanation":"One more is the next counting number. One less is the number just before.","example":"One more than 3 is 4. One less than 3 is 2.","questions":[{"id":"g0-one-more-q1","prompt":"What is one more than 2?","answer":"3","hint":"Count forward one step from 2.","explanation":"2, then 3. One more than 2 is 3.","kind":"numeric","difficulty":"easy"},{"id":"g0-one-more-q2","prompt":"What is one less than 5?","answer":"4","hint":"Count back one step from 5.","explanation":"5, then 4. One less than 5 is 4.","kind":"numeric","difficulty":"medium"},{"id":"g0-one-more-q3","prompt":"You have 6 blocks and get 1 more. How many blocks now?","answer":"7","hint":"Start at 6 and count one more.","explanation":"6 + 1 = 7 blocks.","kind":"numeric","difficulty":"medium"}]}],"x":0,"y":600}') on conflict(id) do update set content=excluded.content;
insert into public.lessons values ('g0-one-more','path-g0-one-more','{"id":"g0-one-more","title":"One more, one less","explanation":"One more is the next counting number. One less is the number just before.","example":"One more than 3 is 4. One less than 3 is 2.","questions":[{"id":"g0-one-more-q1","prompt":"What is one more than 2?","answer":"3","hint":"Count forward one step from 2.","explanation":"2, then 3. One more than 2 is 3.","kind":"numeric","difficulty":"easy"},{"id":"g0-one-more-q2","prompt":"What is one less than 5?","answer":"4","hint":"Count back one step from 5.","explanation":"5, then 4. One less than 5 is 4.","kind":"numeric","difficulty":"medium"},{"id":"g0-one-more-q3","prompt":"You have 6 blocks and get 1 more. How many blocks now?","answer":"7","hint":"Start at 6 and count one more.","explanation":"6 + 1 = 7 blocks.","kind":"numeric","difficulty":"medium"}]}') on conflict(id) do update set content=excluded.content;
