insert into public.units values ('path-g1-make-ten','arithmetic','{"id":"path-g1-make-ten","title":"Make ten","grades":[1],"requires":[],"lessons":[{"id":"g1-make-ten","title":"Make ten","explanation":"Number partners can join to make 10. Count on to find the missing partner.","example":"7 and 3 make 10 because 7 + 3 = 10.","questions":[{"id":"g1-make-ten-q1","prompt":"4 + what number = 10?","answer":"6","hint":"Count from 4 up to 10.","explanation":"4 + 6 = 10. The missing partner is 6.","kind":"numeric","difficulty":"easy"},{"id":"g1-make-ten-q2","prompt":"8 + what number = 10?","answer":"2","hint":"How many more after 8 reach 10?","explanation":"9, 10: two more. 8 + 2 = 10.","kind":"numeric","difficulty":"medium"},{"id":"g1-make-ten-q3","prompt":"There are 3 red beads and some blue beads. There are 10 beads altogether. How many are blue?","answer":"7","hint":"Find the partner that joins 3 to make 10.","explanation":"10 − 3 = 7 blue beads.","kind":"numeric","difficulty":"medium"}]}],"x":260,"y":600}') on conflict(id) do update set content=excluded.content;
insert into public.lessons values ('g1-make-ten','path-g1-make-ten','{"id":"g1-make-ten","title":"Make ten","explanation":"Number partners can join to make 10. Count on to find the missing partner.","example":"7 and 3 make 10 because 7 + 3 = 10.","questions":[{"id":"g1-make-ten-q1","prompt":"4 + what number = 10?","answer":"6","hint":"Count from 4 up to 10.","explanation":"4 + 6 = 10. The missing partner is 6.","kind":"numeric","difficulty":"easy"},{"id":"g1-make-ten-q2","prompt":"8 + what number = 10?","answer":"2","hint":"How many more after 8 reach 10?","explanation":"9, 10: two more. 8 + 2 = 10.","kind":"numeric","difficulty":"medium"},{"id":"g1-make-ten-q3","prompt":"There are 3 red beads and some blue beads. There are 10 beads altogether. How many are blue?","answer":"7","hint":"Find the partner that joins 3 to make 10.","explanation":"10 − 3 = 7 blue beads.","kind":"numeric","difficulty":"medium"}]}') on conflict(id) do update set content=excluded.content;
