insert into public.units values ('path-g1-take-away','arithmetic','{"id":"path-g1-take-away","title":"Taking away within twenty","grades":[1],"requires":["path-g1-make-ten"],"lessons":[{"id":"g1-take-away","title":"Taking away within twenty","explanation":"Subtraction tells how many are left. Start with the total and take away the smaller amount.","example":"12 − 3 = 9. Count back 3 steps: 11, 10, 9.","questions":[{"id":"g1-take-away-q1","prompt":"What is 9 − 4?","answer":"5","hint":"Start at 9 and count back 4 steps.","explanation":"8, 7, 6, 5. So 9 − 4 = 5.","kind":"numeric","difficulty":"easy"},{"id":"g1-take-away-q2","prompt":"What is 15 − 5?","answer":"10","hint":"Take 5 ones away from 15.","explanation":"15 − 5 = 10.","kind":"numeric","difficulty":"medium"},{"id":"g1-take-away-q3","prompt":"A basket holds 14 apples. You give away 6. How many are left?","answer":"8","hint":"Take away 4 to reach 10, then take away 2 more.","explanation":"14 − 4 = 10, and 10 − 2 = 8 apples.","kind":"numeric","difficulty":"medium"}]}],"x":520,"y":600}') on conflict(id) do update set content=excluded.content;
