insert into public.units values ('path-g2-skip-count','arithmetic','{"id":"path-g2-skip-count","title":"Skip-counting patterns","grades":[2],"requires":[],"lessons":[{"id":"g2-skip-count","title":"Skip-counting patterns","explanation":"Skip-counting adds the same amount each time. Look at the gap between neighboring numbers.","example":"Counting by fives: 5, 10, 15, 20. Each jump adds 5.","questions":[{"id":"g2-skip-count-q1","prompt":"What comes next: 2, 4, 6, 8, __?","answer":"10","hint":"Each jump adds 2.","explanation":"8 + 2 = 10.","kind":"numeric","difficulty":"easy"},{"id":"g2-skip-count-q2","prompt":"What comes next: 5, 10, 15, __?","answer":"20","hint":"Keep counting by fives.","explanation":"15 + 5 = 20.","kind":"numeric","difficulty":"medium"},{"id":"g2-skip-count-q3","prompt":"What comes next: 20, 30, 40, __?","answer":"50","hint":"Each jump adds one ten.","explanation":"40 + 10 = 50.","kind":"numeric","difficulty":"medium"}]}],"x":0,"y":800}') on conflict(id) do update set content=excluded.content;
insert into public.lessons values ('g2-skip-count','path-g2-skip-count','{"id":"g2-skip-count","title":"Skip-counting patterns","explanation":"Skip-counting adds the same amount each time. Look at the gap between neighboring numbers.","example":"Counting by fives: 5, 10, 15, 20. Each jump adds 5.","questions":[{"id":"g2-skip-count-q1","prompt":"What comes next: 2, 4, 6, 8, __?","answer":"10","hint":"Each jump adds 2.","explanation":"8 + 2 = 10.","kind":"numeric","difficulty":"easy"},{"id":"g2-skip-count-q2","prompt":"What comes next: 5, 10, 15, __?","answer":"20","hint":"Keep counting by fives.","explanation":"15 + 5 = 20.","kind":"numeric","difficulty":"medium"},{"id":"g2-skip-count-q3","prompt":"What comes next: 20, 30, 40, __?","answer":"50","hint":"Each jump adds one ten.","explanation":"40 + 10 = 50.","kind":"numeric","difficulty":"medium"}]}') on conflict(id) do update set content=excluded.content;
