insert into public.units values ('path-g2-two-digit-sums','arithmetic','{"id":"path-g2-two-digit-sums","title":"Adding tens and ones","grades":[2],"requires":["path-g2-skip-count"],"lessons":[{"id":"g2-two-digit-sums","title":"Adding tens and ones","explanation":"Add tens to tens and ones to ones. Ten ones can regroup into one ten.","example":"24 + 13 = (20 + 10) + (4 + 3) = 30 + 7 = 37.","questions":[{"id":"g2-two-digit-sums-q1","prompt":"What is 32 + 25?","answer":"57","hint":"Add 30 + 20 and 2 + 5.","explanation":"50 + 7 = 57.","kind":"numeric","difficulty":"easy"},{"id":"g2-two-digit-sums-q2","prompt":"What is 47 + 16?","answer":"63","hint":"7 + 6 makes 13 ones: one extra ten and 3 ones.","explanation":"40 + 10 + 13 = 63.","kind":"numeric","difficulty":"medium"},{"id":"g2-two-digit-sums-q3","prompt":"You collect 28 shells and then 35 more. How many shells altogether?","answer":"63","hint":"Add the tens, then regroup 8 + 5 ones.","explanation":"20 + 30 + 8 + 5 = 50 + 13 = 63 shells.","kind":"numeric","difficulty":"medium"}]}],"x":260,"y":800}') on conflict(id) do update set content=excluded.content;
insert into public.lessons values ('g2-two-digit-sums','path-g2-two-digit-sums','{"id":"g2-two-digit-sums","title":"Adding tens and ones","explanation":"Add tens to tens and ones to ones. Ten ones can regroup into one ten.","example":"24 + 13 = (20 + 10) + (4 + 3) = 30 + 7 = 37.","questions":[{"id":"g2-two-digit-sums-q1","prompt":"What is 32 + 25?","answer":"57","hint":"Add 30 + 20 and 2 + 5.","explanation":"50 + 7 = 57.","kind":"numeric","difficulty":"easy"},{"id":"g2-two-digit-sums-q2","prompt":"What is 47 + 16?","answer":"63","hint":"7 + 6 makes 13 ones: one extra ten and 3 ones.","explanation":"40 + 10 + 13 = 63.","kind":"numeric","difficulty":"medium"},{"id":"g2-two-digit-sums-q3","prompt":"You collect 28 shells and then 35 more. How many shells altogether?","answer":"63","hint":"Add the tens, then regroup 8 + 5 ones.","explanation":"20 + 30 + 8 + 5 = 50 + 13 = 63 shells.","kind":"numeric","difficulty":"medium"}]}') on conflict(id) do update set content=excluded.content;
insert into public.questions values ('g2-two-digit-sums-q1','g2-two-digit-sums','numeric','57','{"id":"g2-two-digit-sums-q1","prompt":"What is 32 + 25?","answer":"57","hint":"Add 30 + 20 and 2 + 5.","explanation":"50 + 7 = 57.","kind":"numeric","difficulty":"easy"}') on conflict(id) do update set answer=excluded.answer,content=excluded.content;
