insert into public.units values ('path-g3-arrays','arithmetic','{"id":"path-g3-arrays","title":"Rows and columns","grades":[3],"requires":[],"lessons":[{"id":"g3-arrays","title":"Rows and columns","explanation":"An array has equal rows. Multiply the number of rows by the number in each row.","example":"Three rows of four counters make 3 × 4 = 12 counters.","questions":[{"id":"g3-arrays-q1","prompt":"There are 3 rows with 4 counters in each row. How many counters?","answer":"12","hint":"Add 4 three times, or multiply 3 × 4.","explanation":"4 + 4 + 4 = 12.","visual":{"type":"array","rows":3,"columns":4},"kind":"numeric","difficulty":"easy"},{"id":"g3-arrays-q2","prompt":"There are 4 rows with 5 counters in each row. How many counters?","answer":"20","hint":"Each row adds 5 counters.","explanation":"4 × 5 = 20 counters.","visual":{"type":"array","rows":4,"columns":5},"kind":"numeric","difficulty":"medium"},{"id":"g3-arrays-q3","prompt":"A garden has 6 rows with 3 flowers in each row. How many flowers?","answer":"18","hint":"There are 6 equal groups of 3.","explanation":"6 × 3 = 18 flowers.","visual":{"type":"array","rows":6,"columns":3},"kind":"numeric","difficulty":"medium"}]}],"x":520,"y":800}') on conflict(id) do update set content=excluded.content;
