insert into public.units values ('path-g3-division-facts','arithmetic','{"id":"path-g3-division-facts","title":"Find the missing group","grades":[3],"requires":["path-g3-arrays"],"lessons":[{"id":"g3-division-facts","title":"Find the missing group","explanation":"Multiplication and division are partners. Use a multiplication fact to find a missing group size.","example":"24 ÷ 6 asks: 6 times what makes 24? Since 6 × 4 = 24, the answer is 4.","questions":[{"id":"g3-division-facts-q1","prompt":"What is 21 ÷ 3?","answer":"7","hint":"3 times what makes 21?","explanation":"3 × 7 = 21, so 21 ÷ 3 = 7.","kind":"numeric","difficulty":"easy"},{"id":"g3-division-facts-q2","prompt":"What is 56 ÷ 7?","answer":"8","hint":"Use the 7-times table.","explanation":"7 × 8 = 56, so 56 ÷ 7 = 8.","kind":"numeric","difficulty":"medium"},{"id":"g3-division-facts-q3","prompt":"36 stickers are shared equally among 4 friends. How many does each friend get?","answer":"9","hint":"Find the number that makes 4 equal groups total 36.","explanation":"4 × 9 = 36. Each friend gets 9 stickers.","kind":"numeric","difficulty":"medium"}]}],"x":0,"y":1000}') on conflict(id) do update set content=excluded.content;
