insert into public.units values ('path-g4-factors','arithmetic','{"id":"path-g4-factors","title":"Find the factors","grades":[4],"requires":[],"lessons":[{"id":"g4-factors","title":"Find the factors","explanation":"A factor divides a whole number without a remainder. Factor pairs multiply to make the number.","example":"The factor pairs of 12 are 1 × 12, 2 × 6 and 3 × 4.","questions":[{"id":"g4-factors-q1","prompt":"4 × what whole number = 28?","answer":"7","hint":"Find the partner of 4 in a factor pair of 28.","explanation":"28 ÷ 4 = 7, so 4 × 7 = 28.","kind":"numeric","difficulty":"easy"},{"id":"g4-factors-q2","prompt":"How many positive whole-number factors does 12 have?","answer":"6","hint":"List both numbers from each factor pair, without repeats.","explanation":"The factors are 1, 2, 3, 4, 6 and 12: six factors.","kind":"numeric","difficulty":"medium"},{"id":"g4-factors-q3","prompt":"What is the greatest common factor of 18 and 24?","answer":"6","hint":"List factors shared by both numbers, then choose the greatest.","explanation":"Their common factors are 1, 2, 3 and 6. The greatest is 6.","kind":"numeric","difficulty":"medium"}]}],"x":260,"y":1000}') on conflict(id) do update set content=excluded.content;
