insert into public.units values ('path-g5-decimal-products','arithmetic','{"id":"path-g5-decimal-products","title":"Multiplying decimals","grades":[5],"requires":[],"lessons":[{"id":"g5-decimal-products","title":"Multiplying decimals","explanation":"Multiply as whole numbers, then place the decimal using the total number of decimal places in the factors. Estimate to check the size.","example":"1.2 × 0.3: 12 × 3 = 36. There are two decimal places altogether, so the product is 0.36.","questions":[{"id":"g5-decimal-products-q1","prompt":"What is 0.4 × 0.5?","answer":"0.2","hint":"4 × 5 = 20. Use two decimal places.","explanation":"0.4 × 0.5 = 0.20 = 0.2.","kind":"numeric","difficulty":"easy"},{"id":"g5-decimal-products-q2","prompt":"What is 2.5 × 1.2?","answer":"3","hint":"25 × 12 = 300. Use two decimal places.","explanation":"300 hundredths = 3.00 = 3.","kind":"numeric","difficulty":"medium"},{"id":"g5-decimal-products-q3","prompt":"Three meters of ribbon cost $1.75 per meter. How many dollars is the total cost?","answer":"5.25","hint":"Multiply the price per meter by 3.","explanation":"1.75 × 3 = 5.25 dollars.","kind":"numeric","difficulty":"medium"}]}],"x":520,"y":1000}') on conflict(id) do update set content=excluded.content;
