insert into public.courses values ('fractions','{"id":"fractions","title":"Making sense of fractions","subject":"Arithmetic","grades":[4,5,6],"description":"See the whole picture, and all the parts that make it.","units":[{"id":"parts","title":"Equal parts","x":0,"y":0,"requires":[],"lessons":[{"id":"fractions","title":"Equivalent fractions","explanation":"Multiplying numerator and denominator by the same nonzero number keeps a fraction equal.","example":"1/2 = 2/4 = 3/6.","questions":[{"id":"r1","prompt":"Write 1/2 as a decimal.","answer":"0.5","hint":"Divide 1 by 2.","explanation":"1 ÷ 2 = 0.5. A fraction such as 2/4 is also accepted.","kind":"numeric","difficulty":"easy"},{"id":"r2","prompt":"What is 1/4 + 2/4?","answer":"0.75","hint":"Add the numerators; keep the denominator.","explanation":"1/4 + 2/4 = 3/4 = 0.75.","kind":"numeric","difficulty":"easy"}]}],"grades":[4,5]},{"id":"g6-fraction-division","title":"Fraction division","grades":[6],"lessons":[{"id":"g6-fraction-groups","title":"How many fraction groups?","explanation":"Division can ask how many equal groups fit in an amount. When both fractions have the same denominator, count their equal-sized pieces.","example":"How many 1/4-cup scoops fill 3/4 cup? Three quarter-cup pieces fit: 3/4 ÷ 1/4 = 3.","questions":[{"id":"g6-fraction-groups-q1","prompt":"How many 1/8-meter pieces fit in 5/8 meter?","answer":"5","hint":"Count eighth-sized pieces. Each piece uses one eighth.","explanation":"5/8 is five eighths, so five 1/8-meter pieces fit.","kind":"numeric","difficulty":"easy"},{"id":"g6-fraction-groups-q2","prompt":"How many 2/5-cup servings fit in 4/5 cup?","answer":"2","hint":"The total is four fifths. Each serving uses two fifths.","explanation":"4/5 ÷ 2/5 = 4 ÷ 2 = 2 servings.","kind":"numeric","difficulty":"medium"},{"id":"g6-fraction-groups-q3","prompt":"How many 1/3-meter pieces can you cut from 2 meters?","answer":"6","hint":"Rewrite 2 meters as thirds, then count the pieces.","explanation":"2 = 6/3. Six 1/3-meter pieces fit in 2 meters.","kind":"numeric","difficulty":"medium"}]},{"id":"g6-divide-fractions","title":"Dividing fractions","explanation":"To divide by a nonzero fraction, multiply by its reciprocal. The reciprocal swaps the numerator and denominator. Your answer can be a fraction or a decimal.","example":"3/4 ÷ 2/3 = 3/4 × 3/2 = 9/8. This is a little more than one group, which makes sense because 3/4 is a little larger than 2/3.","questions":[{"id":"g6-divide-fractions-q1","prompt":"Calculate 1/2 ÷ 1/4.","answer":"2","hint":"Multiply 1/2 by 4/1, the reciprocal of 1/4.","explanation":"1/2 × 4/1 = 4/2 = 2.","kind":"numeric","difficulty":"easy"},{"id":"g6-divide-fractions-q2","prompt":"Calculate 2/3 ÷ 4/5. Enter a fraction or decimal.","answer":"5/6","hint":"Keep 2/3 and multiply by 5/4. Then simplify.","explanation":"2/3 × 5/4 = 10/12 = 5/6.","kind":"numeric","difficulty":"medium"},{"id":"g6-divide-fractions-q3","prompt":"A ribbon is 3/4 meter long. Each bow needs 1/8 meter. How many bows can you make?","answer":"6","hint":"Ask how many eighths fit in three quarters.","explanation":"3/4 ÷ 1/8 = 3/4 × 8 = 24/4 = 6 bows.","kind":"numeric","difficulty":"medium"}]}],"requires":[],"x":260,"y":0},{"id":"path-g4-add-like-fractions","title":"Adding equal-sized fraction parts","grades":[4],"requires":[],"lessons":[{"id":"g4-add-like-fractions","title":"Adding equal-sized fraction parts","explanation":"When fractions have the same denominator, add their numerators. The denominator stays the same because the pieces stay the same size.","example":"2/7 + 3/7 = 5/7. Two sevenths and three sevenths make five sevenths.","questions":[{"id":"g4-add-like-fractions-q1","prompt":"What is 1/5 + 2/5? Enter a fraction or decimal.","answer":"3/5","hint":"Add the number of fifth-sized pieces.","explanation":"1 + 2 = 3, so the sum is 3/5.","visual":{"type":"fraction","numerator":3,"denominator":5},"kind":"numeric","difficulty":"easy"},{"id":"g4-add-like-fractions-q2","prompt":"What is 3/8 + 1/8? Enter a fraction or decimal.","answer":"1/2","hint":"4 eighths can be simplified.","explanation":"3/8 + 1/8 = 4/8 = 1/2.","kind":"numeric","difficulty":"medium"},{"id":"g4-add-like-fractions-q3","prompt":"You walk 2/6 kilometer, then 3/6 kilometer. How many kilometers in total?","answer":"5/6","hint":"Both distances use sixths. Add their numerators.","explanation":"2/6 + 3/6 = 5/6 kilometer.","kind":"numeric","difficulty":"medium"}]}],"x":520,"y":0},{"id":"path-g5-multiply-fractions","title":"Multiplying fractions","grades":[5],"requires":[],"lessons":[{"id":"g5-multiply-fractions","title":"Multiplying fractions","explanation":"Multiply numerators, then multiply denominators. Simplify if possible. Multiplying by a fraction less than 1 finds part of an amount.","example":"2/3 × 3/4 = 6/12 = 1/2.","questions":[{"id":"g5-multiply-fractions-q1","prompt":"What is 1/2 × 1/3?","answer":"1/6","hint":"Multiply 1 × 1 and 2 × 3.","explanation":"The product is 1/6.","kind":"numeric","difficulty":"easy"},{"id":"g5-multiply-fractions-q2","prompt":"What is 3/5 × 2/3?","answer":"2/5","hint":"Multiply first, then simplify the result.","explanation":"3/5 × 2/3 = 6/15 = 2/5.","kind":"numeric","difficulty":"medium"},{"id":"g5-multiply-fractions-q3","prompt":"A recipe needs 3/4 cup of flour. You make half the recipe. How many cups of flour do you need?","answer":"3/8","hint":"Find half of 3/4 by multiplying by 1/2.","explanation":"3/4 × 1/2 = 3/8 cup.","kind":"numeric","difficulty":"medium"}]}],"x":0,"y":200}],"planned":false}') on conflict(id) do update set content=excluded.content;
