insert into public.units values ('g6-fraction-division','fractions','{"id":"g6-fraction-division","title":"Fraction division","grades":[6],"lessons":[{"id":"g6-fraction-groups","title":"How many fraction groups?","explanation":"Division can ask how many equal groups fit in an amount. When both fractions have the same denominator, count their equal-sized pieces.","example":"How many 1/4-cup scoops fill 3/4 cup? Three quarter-cup pieces fit: 3/4 ÷ 1/4 = 3.","questions":[{"id":"g6-fraction-groups-q1","prompt":"How many 1/8-meter pieces fit in 5/8 meter?","answer":"5","hint":"Count eighth-sized pieces. Each piece uses one eighth.","explanation":"5/8 is five eighths, so five 1/8-meter pieces fit.","kind":"numeric","difficulty":"easy"},{"id":"g6-fraction-groups-q2","prompt":"How many 2/5-cup servings fit in 4/5 cup?","answer":"2","hint":"The total is four fifths. Each serving uses two fifths.","explanation":"4/5 ÷ 2/5 = 4 ÷ 2 = 2 servings.","kind":"numeric","difficulty":"medium"},{"id":"g6-fraction-groups-q3","prompt":"How many 1/3-meter pieces can you cut from 2 meters?","answer":"6","hint":"Rewrite 2 meters as thirds, then count the pieces.","explanation":"2 = 6/3. Six 1/3-meter pieces fit in 2 meters.","kind":"numeric","difficulty":"medium"}]},{"id":"g6-divide-fractions","title":"Dividing fractions","explanation":"To divide by a nonzero fraction, multiply by its reciprocal. The reciprocal swaps the numerator and denominator. Your answer can be a fraction or a decimal.","example":"3/4 ÷ 2/3 = 3/4 × 3/2 = 9/8. This is a little more than one group, which makes sense because 3/4 is a little larger than 2/3.","questions":[{"id":"g6-divide-fractions-q1","prompt":"Calculate 1/2 ÷ 1/4.","answer":"2","hint":"Multiply 1/2 by 4/1, the reciprocal of 1/4.","explanation":"1/2 × 4/1 = 4/2 = 2.","kind":"numeric","difficulty":"easy"},{"id":"g6-divide-fractions-q2","prompt":"Calculate 2/3 ÷ 4/5. Enter a fraction or decimal.","answer":"5/6","hint":"Keep 2/3 and multiply by 5/4. Then simplify.","explanation":"2/3 × 5/4 = 10/12 = 5/6.","kind":"numeric","difficulty":"medium"},{"id":"g6-divide-fractions-q3","prompt":"A ribbon is 3/4 meter long. Each bow needs 1/8 meter. How many bows can you make?","answer":"6","hint":"Ask how many eighths fit in three quarters.","explanation":"3/4 ÷ 1/8 = 3/4 × 8 = 24/4 = 6 bows.","kind":"numeric","difficulty":"medium"}]}],"requires":[],"x":260,"y":0}') on conflict(id) do update set content=excluded.content;
insert into public.lessons values ('g6-fraction-groups','g6-fraction-division','{"id":"g6-fraction-groups","title":"How many fraction groups?","explanation":"Division can ask how many equal groups fit in an amount. When both fractions have the same denominator, count their equal-sized pieces.","example":"How many 1/4-cup scoops fill 3/4 cup? Three quarter-cup pieces fit: 3/4 ÷ 1/4 = 3.","questions":[{"id":"g6-fraction-groups-q1","prompt":"How many 1/8-meter pieces fit in 5/8 meter?","answer":"5","hint":"Count eighth-sized pieces. Each piece uses one eighth.","explanation":"5/8 is five eighths, so five 1/8-meter pieces fit.","kind":"numeric","difficulty":"easy"},{"id":"g6-fraction-groups-q2","prompt":"How many 2/5-cup servings fit in 4/5 cup?","answer":"2","hint":"The total is four fifths. Each serving uses two fifths.","explanation":"4/5 ÷ 2/5 = 4 ÷ 2 = 2 servings.","kind":"numeric","difficulty":"medium"},{"id":"g6-fraction-groups-q3","prompt":"How many 1/3-meter pieces can you cut from 2 meters?","answer":"6","hint":"Rewrite 2 meters as thirds, then count the pieces.","explanation":"2 = 6/3. Six 1/3-meter pieces fit in 2 meters.","kind":"numeric","difficulty":"medium"}]}') on conflict(id) do update set content=excluded.content;
