insert into public.units values ('path-g4-add-like-fractions','fractions','{"id":"path-g4-add-like-fractions","title":"Adding equal-sized fraction parts","grades":[4],"requires":[],"lessons":[{"id":"g4-add-like-fractions","title":"Adding equal-sized fraction parts","explanation":"When fractions have the same denominator, add their numerators. The denominator stays the same because the pieces stay the same size.","example":"2/7 + 3/7 = 5/7. Two sevenths and three sevenths make five sevenths.","questions":[{"id":"g4-add-like-fractions-q1","prompt":"What is 1/5 + 2/5? Enter a fraction or decimal.","answer":"3/5","hint":"Add the number of fifth-sized pieces.","explanation":"1 + 2 = 3, so the sum is 3/5.","visual":{"type":"fraction","numerator":3,"denominator":5},"kind":"numeric","difficulty":"easy"},{"id":"g4-add-like-fractions-q2","prompt":"What is 3/8 + 1/8? Enter a fraction or decimal.","answer":"1/2","hint":"4 eighths can be simplified.","explanation":"3/8 + 1/8 = 4/8 = 1/2.","kind":"numeric","difficulty":"medium"},{"id":"g4-add-like-fractions-q3","prompt":"You walk 2/6 kilometer, then 3/6 kilometer. How many kilometers in total?","answer":"5/6","hint":"Both distances use sixths. Add their numerators.","explanation":"2/6 + 3/6 = 5/6 kilometer.","kind":"numeric","difficulty":"medium"}]}],"x":520,"y":0}') on conflict(id) do update set content=excluded.content;
insert into public.lessons values ('g4-add-like-fractions','path-g4-add-like-fractions','{"id":"g4-add-like-fractions","title":"Adding equal-sized fraction parts","explanation":"When fractions have the same denominator, add their numerators. The denominator stays the same because the pieces stay the same size.","example":"2/7 + 3/7 = 5/7. Two sevenths and three sevenths make five sevenths.","questions":[{"id":"g4-add-like-fractions-q1","prompt":"What is 1/5 + 2/5? Enter a fraction or decimal.","answer":"3/5","hint":"Add the number of fifth-sized pieces.","explanation":"1 + 2 = 3, so the sum is 3/5.","visual":{"type":"fraction","numerator":3,"denominator":5},"kind":"numeric","difficulty":"easy"},{"id":"g4-add-like-fractions-q2","prompt":"What is 3/8 + 1/8? Enter a fraction or decimal.","answer":"1/2","hint":"4 eighths can be simplified.","explanation":"3/8 + 1/8 = 4/8 = 1/2.","kind":"numeric","difficulty":"medium"},{"id":"g4-add-like-fractions-q3","prompt":"You walk 2/6 kilometer, then 3/6 kilometer. How many kilometers in total?","answer":"5/6","hint":"Both distances use sixths. Add their numerators.","explanation":"2/6 + 3/6 = 5/6 kilometer.","kind":"numeric","difficulty":"medium"}]}') on conflict(id) do update set content=excluded.content;
