insert into public.units values ('path-g5-multiply-fractions','fractions','{"id":"path-g5-multiply-fractions","title":"Multiplying fractions","grades":[5],"requires":[],"lessons":[{"id":"g5-multiply-fractions","title":"Multiplying fractions","explanation":"Multiply numerators, then multiply denominators. Simplify if possible. Multiplying by a fraction less than 1 finds part of an amount.","example":"2/3 × 3/4 = 6/12 = 1/2.","questions":[{"id":"g5-multiply-fractions-q1","prompt":"What is 1/2 × 1/3?","answer":"1/6","hint":"Multiply 1 × 1 and 2 × 3.","explanation":"The product is 1/6.","kind":"numeric","difficulty":"easy"},{"id":"g5-multiply-fractions-q2","prompt":"What is 3/5 × 2/3?","answer":"2/5","hint":"Multiply first, then simplify the result.","explanation":"3/5 × 2/3 = 6/15 = 2/5.","kind":"numeric","difficulty":"medium"},{"id":"g5-multiply-fractions-q3","prompt":"A recipe needs 3/4 cup of flour. You make half the recipe. How many cups of flour do you need?","answer":"3/8","hint":"Find half of 3/4 by multiplying by 1/2.","explanation":"3/4 × 1/2 = 3/8 cup.","kind":"numeric","difficulty":"medium"}]}],"x":0,"y":200}') on conflict(id) do update set content=excluded.content;
