insert into public.courses values ('algebra','{"id":"algebra","title":"Algebra I","subject":"Algebra I","grades":[6,7,8,9,11],"description":"From your first variable to a world of possibilities.","units":[{"id":"foundations","title":"Foundations","x":260,"y":0,"requires":[],"lessons":[{"id":"order","title":"Order of operations","explanation":"Evaluate parentheses, then powers, then multiplication and division, then addition and subtraction.","example":"3 + 2 × 4 = 3 + 8 = 11.","questions":[{"id":"o1","prompt":"Evaluate 6 + 3 × 4.","answer":"18","hint":"Multiply first.","explanation":"3 × 4 = 12, then 6 + 12 = 18.","kind":"numeric","difficulty":"easy"},{"id":"o2","prompt":"Evaluate (6 + 3) × 4.","answer":"36","hint":"Start inside the parentheses.","explanation":"6 + 3 = 9, then 9 × 4 = 36.","kind":"numeric","difficulty":"easy"}]}],"grades":[6,7,8,9]},{"id":"expressions","title":"Expressions","x":80,"y":170,"requires":["foundations"],"lessons":[{"id":"combine","title":"Combine like terms","explanation":"Terms with the same variable and exponent can be added by combining coefficients.","example":"3x + 2x = (3 + 2)x = 5x.","questions":[{"id":"e1","prompt":"Simplify 4x + 3x.","answer":"7x","hint":"Add the coefficients.","explanation":"(4 + 3)x = 7x.","kind":"expression","difficulty":"easy"},{"id":"e2","prompt":"Evaluate 2x + 5 when x = 3.","answer":"11","hint":"Replace x with 3.","explanation":"2 × 3 + 5 = 6 + 5 = 11.","kind":"numeric","difficulty":"easy"}]}],"grades":[6,7,8,9]},{"id":"equations","title":"Linear equations","x":440,"y":170,"requires":["foundations"],"lessons":[{"id":"solve","title":"Solve linear equations","explanation":"Keep an equation balanced by doing the same operation on both sides.","example":"2x + 4 = 12 → 2x = 8 → x = 4.","questions":[{"id":"l1","prompt":"Solve 3x + 5 = 20. Enter x.","answer":"5","hint":"Subtract 5, then divide by 3.","explanation":"3x = 15, so x = 5.","kind":"numeric","difficulty":"easy"},{"id":"l2","prompt":"Solve 4x − 8 = 16. Enter x.","answer":"6","hint":"Add 8 to both sides.","explanation":"4x = 24, so x = 6.","kind":"numeric","difficulty":"easy"}]}],"grades":[7,8,9]},{"id":"inequalities","title":"Inequalities","x":0,"y":350,"requires":["expressions","equations"],"lessons":[{"id":"inequality","title":"Compare solutions","explanation":"An inequality describes a range. Reverse the inequality when multiplying or dividing by a negative number.","example":"−2x < 6 → x > −3.","questions":[{"id":"i1","prompt":"Solve 2x + 1 < 9.","answer":"x < 4","hint":"Subtract 1 and divide by 2.","explanation":"2x < 8 gives x < 4.","kind":"choice","choices":["x < 4","x > 4","x < 5"],"difficulty":"easy"},{"id":"i2","prompt":"Solve −3x > 12.","answer":"x < -4","hint":"Division by a negative reverses the sign.","explanation":"Divide both sides by −3 to get x < −4.","kind":"choice","choices":["x > -4","x < -4","x < 4"],"difficulty":"easy"}]}],"grades":[7,9]},{"id":"functions","title":"Functions","x":260,"y":350,"requires":["expressions","equations"],"lessons":[{"id":"function","title":"Inputs and outputs","explanation":"A function assigns exactly one output to each input. Substitute the input for x.","example":"For f(x) = 2x + 1, f(3) = 7.","questions":[{"id":"f1","prompt":"If f(x) = 3x − 2, find f(4).","answer":"10","hint":"Substitute 4 for x.","explanation":"3 × 4 − 2 = 10.","kind":"numeric","difficulty":"easy"},{"id":"f2","prompt":"If g(x) = x² + 1, find g(−3).","answer":"10","hint":"Square −3 before adding 1.","explanation":"(−3)² + 1 = 9 + 1 = 10.","kind":"numeric","difficulty":"easy"}]}],"grades":[8,9]},{"id":"systems","title":"Systems","x":520,"y":350,"requires":["equations"],"lessons":[{"id":"system","title":"Solve a system","explanation":"A solution satisfies both equations. Substitution replaces a variable with an equal expression.","example":"y = x + 1 and x + y = 5 → 2x + 1 = 5 → x = 2, y = 3.","questions":[{"id":"s1","prompt":"If y = x + 2 and x + y = 10, find x.","answer":"4","hint":"Replace y with x + 2.","explanation":"x + x + 2 = 10 → 2x = 8 → x = 4.","kind":"numeric","difficulty":"easy"},{"id":"s2","prompt":"For that same system, find y.","answer":"6","hint":"Use x = 4 in y = x + 2.","explanation":"y = 4 + 2 = 6.","kind":"numeric","difficulty":"easy"}]}],"grades":[8,9]},{"id":"quadratics","title":"Quadratics","x":260,"y":530,"requires":["functions","systems"],"lessons":[{"id":"quadratic","title":"Quadratic roots","explanation":"A quadratic can have two real roots. If a product equals zero, at least one factor is zero.","example":"x² − 9 = (x − 3)(x + 3), so x = 3 or x = −3.","questions":[{"id":"q1","prompt":"What are the roots of x² − 16 = 0?","answer":"-4 and 4","hint":"Which two numbers square to 16?","explanation":"x² = 16 gives x = −4 or x = 4.","kind":"choice","choices":["-4 and 4","4 only","-8 and 8"],"difficulty":"medium"},{"id":"q2","prompt":"What is the positive root of x² − 25 = 0?","answer":"5","hint":"Take the positive square root of 25.","explanation":"x² = 25, so the positive root is 5.","kind":"numeric","difficulty":"easy"}]}],"grades":[9,11]},{"id":"g6-substitution","title":"Using variables","grades":[6],"lessons":[{"id":"g6-evaluate-expressions","title":"Putting numbers into expressions","explanation":"A variable stands for a number. Replace the variable with its value, then follow the order of operations. A number next to a variable means multiplication.","example":"When n = 4, the expression 3n + 2 means 3 × 4 + 2 = 14. Multiply before adding.","questions":[{"id":"g6-evaluate-expressions-q1","prompt":"Evaluate 5n + 1 when n = 3.","answer":"16","hint":"Replace n with 3. Multiply 5 × 3 before adding 1.","explanation":"5 × 3 + 1 = 15 + 1 = 16.","kind":"numeric","difficulty":"easy"},{"id":"g6-evaluate-expressions-q2","prompt":"Evaluate 2(a + 4) when a = 5.","answer":"18","hint":"Replace a with 5. Work inside the parentheses first.","explanation":"2 × (5 + 4) = 2 × 9 = 18.","kind":"numeric","difficulty":"medium"},{"id":"g6-evaluate-expressions-q3","prompt":"Evaluate x² + 3 when x = 4.","answer":"19","hint":"The exponent means 4 × 4, not 4 × 2.","explanation":"4² + 3 = 16 + 3 = 19.","kind":"numeric","difficulty":"medium"}]}],"requires":["expressions"],"x":0,"y":540},{"id":"path-g6-one-step-equations","title":"Balance a one-step equation","grades":[6],"requires":[],"lessons":[{"id":"g6-one-step-equations","title":"Balance a one-step equation","explanation":"An equation is balanced: both sides have the same value. Use an inverse operation on both sides to find the unknown.","example":"x + 7 = 12. Subtract 7 from both sides: x = 5. Check: 5 + 7 = 12.","questions":[{"id":"g6-one-step-equations-q1","prompt":"Find x: x + 9 = 20.","answer":"11","hint":"Undo adding 9 by subtracting 9 from both sides.","explanation":"x = 20 − 9 = 11.","kind":"numeric","difficulty":"easy"},{"id":"g6-one-step-equations-q2","prompt":"Find x: 4x = 28.","answer":"7","hint":"Undo multiplying by 4 by dividing both sides by 4.","explanation":"x = 28 ÷ 4 = 7.","kind":"numeric","difficulty":"medium"},{"id":"g6-one-step-equations-q3","prompt":"Find x: x/3 = 5.","answer":"15","hint":"Multiply both sides by 3.","explanation":"x = 5 × 3 = 15. Check: 15 ÷ 3 = 5.","kind":"numeric","difficulty":"medium"}]}],"x":0,"y":740},{"id":"path-g8-slope","title":"Slope as a rate of change","grades":[8],"requires":[],"lessons":[{"id":"g8-slope","title":"Slope as a rate of change","explanation":"Slope compares a change in y with a change in x: slope = change in y ÷ change in x. Keep the same point order in both changes.","example":"Between (1, 2) and (3, 8), the slope is (8 − 2) ÷ (3 − 1) = 3.","questions":[{"id":"g8-slope-q1","prompt":"Find the slope between (0, 1) and (2, 5).","answer":"2","hint":"Divide the vertical change by the horizontal change.","explanation":"(5 − 1) ÷ (2 − 0) = 4 ÷ 2 = 2.","kind":"numeric","difficulty":"easy"},{"id":"g8-slope-q2","prompt":"Find the slope between (1, 7) and (4, 1).","answer":"-2","hint":"The change in y is negative while the change in x is positive.","explanation":"(1 − 7) ÷ (4 − 1) = −6 ÷ 3 = −2.","kind":"numeric","difficulty":"medium"},{"id":"g8-slope-q3","prompt":"A tank''s water level rises 12 cm in 8 minutes at a steady rate. How many centimeters per minute is that?","answer":"1.5","hint":"Divide the total rise by the time.","explanation":"12 ÷ 8 = 1.5 centimeters per minute.","kind":"numeric","difficulty":"medium"}]}],"x":260,"y":740},{"id":"path-g8-two-step-equations","title":"Solve two-step equations","grades":[8],"requires":["path-g8-slope"],"lessons":[{"id":"g8-two-step-equations","title":"Solve two-step equations","explanation":"Undo addition or subtraction first, then undo multiplication or division. Apply each operation to both sides.","example":"3x + 4 = 19. Subtract 4 to get 3x = 15, then divide by 3 to get x = 5.","questions":[{"id":"g8-two-step-equations-q1","prompt":"Find x: 2x + 5 = 17.","answer":"6","hint":"Subtract 5, then divide by 2.","explanation":"2x = 12, so x = 6.","kind":"numeric","difficulty":"easy"},{"id":"g8-two-step-equations-q2","prompt":"Find x: 5x − 8 = 12.","answer":"4","hint":"Add 8 to both sides, then divide by 5.","explanation":"5x = 20, so x = 4.","kind":"numeric","difficulty":"medium"},{"id":"g8-two-step-equations-q3","prompt":"Find x: 3(x + 2) = 21.","answer":"5","hint":"Divide both sides by 3 before subtracting 2.","explanation":"x + 2 = 7, so x = 5.","kind":"numeric","difficulty":"medium"}]}],"x":520,"y":740},{"id":"path-g9-linear-rules","title":"Read a linear rule","grades":[9],"requires":[],"lessons":[{"id":"g9-linear-rules","title":"Read a linear rule","explanation":"In y = mx + b, m is the slope and b is the y-intercept. Substitute an input to find its output.","example":"For y = 2x + 3, the slope is 2, the y-intercept is 3, and x = 4 gives y = 11.","questions":[{"id":"g9-linear-rules-q1","prompt":"For y = 3x − 2, find y when x = 5.","answer":"13","hint":"Replace x with 5 and multiply before subtracting.","explanation":"y = 3 × 5 − 2 = 13.","kind":"numeric","difficulty":"easy"},{"id":"g9-linear-rules-q2","prompt":"What is the y-intercept of y = −4x + 7?","answer":"7","hint":"The y-intercept is the output when x = 0.","explanation":"y = −4 × 0 + 7 = 7.","kind":"numeric","difficulty":"medium"},{"id":"g9-linear-rules-q3","prompt":"For y = −2x + 9, what is x when y = 1?","answer":"4","hint":"Set 1 = −2x + 9 and solve for x.","explanation":"−8 = −2x, so x = 4.","kind":"numeric","difficulty":"medium"}]}],"x":780,"y":740},{"id":"path-g9-powers","title":"Working with powers","grades":[9],"requires":["path-g9-linear-rules"],"lessons":[{"id":"g9-powers","title":"Working with powers","explanation":"Multiplying powers with the same base adds their exponents. A power raised to a power multiplies exponents.","example":"2³ × 2² = 2⁵ = 32. Also, (2³)² = 2⁶ = 64.","questions":[{"id":"g9-powers-q1","prompt":"Evaluate 2³ × 2⁴.","answer":"128","hint":"Add the exponents because the bases are the same.","explanation":"2⁷ = 128.","kind":"numeric","difficulty":"easy"},{"id":"g9-powers-q2","prompt":"Evaluate (3²)².","answer":"81","hint":"Multiply the exponents 2 × 2.","explanation":"3⁴ = 81.","kind":"numeric","difficulty":"medium"},{"id":"g9-powers-q3","prompt":"Evaluate 5³ ÷ 5².","answer":"5","hint":"When dividing powers with the same nonzero base, subtract exponents.","explanation":"5³ ÷ 5² = 5¹ = 5.","kind":"numeric","difficulty":"medium"}]}],"x":1040,"y":740}],"planned":false}') on conflict(id) do update set content=excluded.content;
