insert into public.units values ('systems','algebra','{"id":"systems","title":"Systems","x":520,"y":350,"requires":["equations"],"lessons":[{"id":"system","title":"Solve a system","explanation":"A solution satisfies both equations. Substitution replaces a variable with an equal expression.","example":"y = x + 1 and x + y = 5 → 2x + 1 = 5 → x = 2, y = 3.","questions":[{"id":"s1","prompt":"If y = x + 2 and x + y = 10, find x.","answer":"4","hint":"Replace y with x + 2.","explanation":"x + x + 2 = 10 → 2x = 8 → x = 4.","kind":"numeric","difficulty":"easy"},{"id":"s2","prompt":"For that same system, find y.","answer":"6","hint":"Use x = 4 in y = x + 2.","explanation":"y = 4 + 2 = 6.","kind":"numeric","difficulty":"easy"}]}],"grades":[8,9]}') on conflict(id) do update set content=excluded.content;
