insert into public.units values ('path-g6-one-step-equations','algebra','{"id":"path-g6-one-step-equations","title":"Balance a one-step equation","grades":[6],"requires":[],"lessons":[{"id":"g6-one-step-equations","title":"Balance a one-step equation","explanation":"An equation is balanced: both sides have the same value. Use an inverse operation on both sides to find the unknown.","example":"x + 7 = 12. Subtract 7 from both sides: x = 5. Check: 5 + 7 = 12.","questions":[{"id":"g6-one-step-equations-q1","prompt":"Find x: x + 9 = 20.","answer":"11","hint":"Undo adding 9 by subtracting 9 from both sides.","explanation":"x = 20 − 9 = 11.","kind":"numeric","difficulty":"easy"},{"id":"g6-one-step-equations-q2","prompt":"Find x: 4x = 28.","answer":"7","hint":"Undo multiplying by 4 by dividing both sides by 4.","explanation":"x = 28 ÷ 4 = 7.","kind":"numeric","difficulty":"medium"},{"id":"g6-one-step-equations-q3","prompt":"Find x: x/3 = 5.","answer":"15","hint":"Multiply both sides by 3.","explanation":"x = 5 × 3 = 15. Check: 15 ÷ 3 = 5.","kind":"numeric","difficulty":"medium"}]}],"x":0,"y":740}') on conflict(id) do update set content=excluded.content;
insert into public.lessons values ('g6-one-step-equations','path-g6-one-step-equations','{"id":"g6-one-step-equations","title":"Balance a one-step equation","explanation":"An equation is balanced: both sides have the same value. Use an inverse operation on both sides to find the unknown.","example":"x + 7 = 12. Subtract 7 from both sides: x = 5. Check: 5 + 7 = 12.","questions":[{"id":"g6-one-step-equations-q1","prompt":"Find x: x + 9 = 20.","answer":"11","hint":"Undo adding 9 by subtracting 9 from both sides.","explanation":"x = 20 − 9 = 11.","kind":"numeric","difficulty":"easy"},{"id":"g6-one-step-equations-q2","prompt":"Find x: 4x = 28.","answer":"7","hint":"Undo multiplying by 4 by dividing both sides by 4.","explanation":"x = 28 ÷ 4 = 7.","kind":"numeric","difficulty":"medium"},{"id":"g6-one-step-equations-q3","prompt":"Find x: x/3 = 5.","answer":"15","hint":"Multiply both sides by 3.","explanation":"x = 5 × 3 = 15. Check: 15 ÷ 3 = 5.","kind":"numeric","difficulty":"medium"}]}') on conflict(id) do update set content=excluded.content;
