insert into public.units values ('path-g8-slope','algebra','{"id":"path-g8-slope","title":"Slope as a rate of change","grades":[8],"requires":[],"lessons":[{"id":"g8-slope","title":"Slope as a rate of change","explanation":"Slope compares a change in y with a change in x: slope = change in y ÷ change in x. Keep the same point order in both changes.","example":"Between (1, 2) and (3, 8), the slope is (8 − 2) ÷ (3 − 1) = 3.","questions":[{"id":"g8-slope-q1","prompt":"Find the slope between (0, 1) and (2, 5).","answer":"2","hint":"Divide the vertical change by the horizontal change.","explanation":"(5 − 1) ÷ (2 − 0) = 4 ÷ 2 = 2.","kind":"numeric","difficulty":"easy"},{"id":"g8-slope-q2","prompt":"Find the slope between (1, 7) and (4, 1).","answer":"-2","hint":"The change in y is negative while the change in x is positive.","explanation":"(1 − 7) ÷ (4 − 1) = −6 ÷ 3 = −2.","kind":"numeric","difficulty":"medium"},{"id":"g8-slope-q3","prompt":"A tank''s water level rises 12 cm in 8 minutes at a steady rate. How many centimeters per minute is that?","answer":"1.5","hint":"Divide the total rise by the time.","explanation":"12 ÷ 8 = 1.5 centimeters per minute.","kind":"numeric","difficulty":"medium"}]}],"x":260,"y":740}') on conflict(id) do update set content=excluded.content;
insert into public.lessons values ('g8-slope','path-g8-slope','{"id":"g8-slope","title":"Slope as a rate of change","explanation":"Slope compares a change in y with a change in x: slope = change in y ÷ change in x. Keep the same point order in both changes.","example":"Between (1, 2) and (3, 8), the slope is (8 − 2) ÷ (3 − 1) = 3.","questions":[{"id":"g8-slope-q1","prompt":"Find the slope between (0, 1) and (2, 5).","answer":"2","hint":"Divide the vertical change by the horizontal change.","explanation":"(5 − 1) ÷ (2 − 0) = 4 ÷ 2 = 2.","kind":"numeric","difficulty":"easy"},{"id":"g8-slope-q2","prompt":"Find the slope between (1, 7) and (4, 1).","answer":"-2","hint":"The change in y is negative while the change in x is positive.","explanation":"(1 − 7) ÷ (4 − 1) = −6 ÷ 3 = −2.","kind":"numeric","difficulty":"medium"},{"id":"g8-slope-q3","prompt":"A tank''s water level rises 12 cm in 8 minutes at a steady rate. How many centimeters per minute is that?","answer":"1.5","hint":"Divide the total rise by the time.","explanation":"12 ÷ 8 = 1.5 centimeters per minute.","kind":"numeric","difficulty":"medium"}]}') on conflict(id) do update set content=excluded.content;
