insert into public.units values ('path-g8-two-step-equations','algebra','{"id":"path-g8-two-step-equations","title":"Solve two-step equations","grades":[8],"requires":["path-g8-slope"],"lessons":[{"id":"g8-two-step-equations","title":"Solve two-step equations","explanation":"Undo addition or subtraction first, then undo multiplication or division. Apply each operation to both sides.","example":"3x + 4 = 19. Subtract 4 to get 3x = 15, then divide by 3 to get x = 5.","questions":[{"id":"g8-two-step-equations-q1","prompt":"Find x: 2x + 5 = 17.","answer":"6","hint":"Subtract 5, then divide by 2.","explanation":"2x = 12, so x = 6.","kind":"numeric","difficulty":"easy"},{"id":"g8-two-step-equations-q2","prompt":"Find x: 5x − 8 = 12.","answer":"4","hint":"Add 8 to both sides, then divide by 5.","explanation":"5x = 20, so x = 4.","kind":"numeric","difficulty":"medium"},{"id":"g8-two-step-equations-q3","prompt":"Find x: 3(x + 2) = 21.","answer":"5","hint":"Divide both sides by 3 before subtracting 2.","explanation":"x + 2 = 7, so x = 5.","kind":"numeric","difficulty":"medium"}]}],"x":520,"y":740}') on conflict(id) do update set content=excluded.content;
