insert into public.units values ('path-g9-linear-rules','algebra','{"id":"path-g9-linear-rules","title":"Read a linear rule","grades":[9],"requires":[],"lessons":[{"id":"g9-linear-rules","title":"Read a linear rule","explanation":"In y = mx + b, m is the slope and b is the y-intercept. Substitute an input to find its output.","example":"For y = 2x + 3, the slope is 2, the y-intercept is 3, and x = 4 gives y = 11.","questions":[{"id":"g9-linear-rules-q1","prompt":"For y = 3x − 2, find y when x = 5.","answer":"13","hint":"Replace x with 5 and multiply before subtracting.","explanation":"y = 3 × 5 − 2 = 13.","kind":"numeric","difficulty":"easy"},{"id":"g9-linear-rules-q2","prompt":"What is the y-intercept of y = −4x + 7?","answer":"7","hint":"The y-intercept is the output when x = 0.","explanation":"y = −4 × 0 + 7 = 7.","kind":"numeric","difficulty":"medium"},{"id":"g9-linear-rules-q3","prompt":"For y = −2x + 9, what is x when y = 1?","answer":"4","hint":"Set 1 = −2x + 9 and solve for x.","explanation":"−8 = −2x, so x = 4.","kind":"numeric","difficulty":"medium"}]}],"x":780,"y":740}') on conflict(id) do update set content=excluded.content;
insert into public.lessons values ('g9-linear-rules','path-g9-linear-rules','{"id":"g9-linear-rules","title":"Read a linear rule","explanation":"In y = mx + b, m is the slope and b is the y-intercept. Substitute an input to find its output.","example":"For y = 2x + 3, the slope is 2, the y-intercept is 3, and x = 4 gives y = 11.","questions":[{"id":"g9-linear-rules-q1","prompt":"For y = 3x − 2, find y when x = 5.","answer":"13","hint":"Replace x with 5 and multiply before subtracting.","explanation":"y = 3 × 5 − 2 = 13.","kind":"numeric","difficulty":"easy"},{"id":"g9-linear-rules-q2","prompt":"What is the y-intercept of y = −4x + 7?","answer":"7","hint":"The y-intercept is the output when x = 0.","explanation":"y = −4 × 0 + 7 = 7.","kind":"numeric","difficulty":"medium"},{"id":"g9-linear-rules-q3","prompt":"For y = −2x + 9, what is x when y = 1?","answer":"4","hint":"Set 1 = −2x + 9 and solve for x.","explanation":"−8 = −2x, so x = 4.","kind":"numeric","difficulty":"medium"}]}') on conflict(id) do update set content=excluded.content;
