insert into public.units values ('path-g9-powers','algebra','{"id":"path-g9-powers","title":"Working with powers","grades":[9],"requires":["path-g9-linear-rules"],"lessons":[{"id":"g9-powers","title":"Working with powers","explanation":"Multiplying powers with the same base adds their exponents. A power raised to a power multiplies exponents.","example":"2³ × 2² = 2⁵ = 32. Also, (2³)² = 2⁶ = 64.","questions":[{"id":"g9-powers-q1","prompt":"Evaluate 2³ × 2⁴.","answer":"128","hint":"Add the exponents because the bases are the same.","explanation":"2⁷ = 128.","kind":"numeric","difficulty":"easy"},{"id":"g9-powers-q2","prompt":"Evaluate (3²)².","answer":"81","hint":"Multiply the exponents 2 × 2.","explanation":"3⁴ = 81.","kind":"numeric","difficulty":"medium"},{"id":"g9-powers-q3","prompt":"Evaluate 5³ ÷ 5².","answer":"5","hint":"When dividing powers with the same nonzero base, subtract exponents.","explanation":"5³ ÷ 5² = 5¹ = 5.","kind":"numeric","difficulty":"medium"}]}],"x":1040,"y":740}') on conflict(id) do update set content=excluded.content;
