insert into public.courses values ('pre-algebra','{"id":"pre-algebra","title":"Pre-Algebra","subject":"Pre-Algebra","grades":[6,7],"description":"Explore introductory pre-algebra lessons.","units":[{"id":"ratios","title":"Ratios and unit rates","grades":[6],"requires":[],"x":0,"y":0,"lessons":[{"id":"ratios-practice","title":"Ratios and unit rates","explanation":"A unit rate tells you the amount for one. Divide the total by the number of units.","example":"12 dollars for 3 books means 4 dollars per book.","questions":[{"id":"ratios-q1","prompt":"Four notebooks cost $12. What is the cost of one notebook?","answer":"3","hint":"A unit rate tells you the amount for one. Divide the total by the number of units.","explanation":"12 ÷ 4 = 3 dollars per notebook.","kind":"numeric","difficulty":"easy"},{"id":"ratios-q2","prompt":"A cyclist travels 30 miles in 2 hours. What is the average speed in miles per hour?","answer":"15","hint":"A unit rate tells you the amount for one. Divide the total by the number of units.","explanation":"30 ÷ 2 = 15 miles per hour.","kind":"numeric","difficulty":"easy"}]},{"id":"g6-equivalent-ratios","title":"Building equivalent ratios","explanation":"Equivalent ratios describe the same relationship. Multiply or divide both quantities by the same nonzero number.","example":"A mix has 2 cups of juice for 3 cups of water. Doubling both gives 4 cups of juice for 6 cups of water: 2:3 = 4:6.","questions":[{"id":"g6-equivalent-ratios-q1","prompt":"A recipe uses 2 cups of oats for 3 cups of milk. How many cups of milk go with 6 cups of oats?","answer":"9","hint":"The oats increased from 2 to 6. Use that same multiplier for the milk.","explanation":"6 ÷ 2 = 3, so multiply the milk by 3: 3 × 3 = 9 cups.","kind":"numeric","difficulty":"easy"},{"id":"g6-equivalent-ratios-q2","prompt":"The ratio of blue beads to red beads is 3:5. If there are 20 red beads, how many blue beads are there?","answer":"12","hint":"Find how many times 5 fits into 20, then scale the 3 blue beads.","explanation":"20 ÷ 5 = 4, so there are 3 × 4 = 12 blue beads.","kind":"numeric","difficulty":"medium"},{"id":"g6-equivalent-ratios-q3","prompt":"Four notebooks cost $6 in total. At the same price per notebook, how many dollars do 10 notebooks cost?","answer":"15","hint":"Find the price of one notebook, then multiply by 10.","explanation":"$6 ÷ 4 = $1.50 each. Ten cost 10 × $1.50 = $15.","kind":"numeric","difficulty":"medium"}]}]},{"id":"integers","title":"Working with negative numbers","grades":[6],"requires":["ratios"],"x":260,"y":0,"lessons":[{"id":"integers-practice","title":"Working with negative numbers","explanation":"Adding a negative moves left on a number line. Subtracting a negative is adding its opposite.","example":"3 + (−5) = −2.","questions":[{"id":"integers-q1","prompt":"What is −4 + 9?","answer":"5","hint":"Adding a negative moves left on a number line. Subtracting a negative is adding its opposite.","explanation":"Moving 9 places right from −4 gives 5.","kind":"numeric","difficulty":"easy"},{"id":"integers-q2","prompt":"What is 6 − (−3)?","answer":"9","hint":"Adding a negative moves left on a number line. Subtracting a negative is adding its opposite.","explanation":"Subtracting −3 is the same as adding 3: 6 + 3 = 9.","kind":"numeric","difficulty":"easy"}]}]},{"id":"proportions","title":"Proportional relationships","grades":[7],"requires":["ratios"],"x":520,"y":0,"lessons":[{"id":"proportions-practice","title":"Proportional relationships","explanation":"In a proportional relationship, the ratio between two quantities stays constant.","example":"If y = 3x, then x = 4 gives y = 12.","questions":[{"id":"proportions-q1","prompt":"If y = 4x, what is y when x = 6?","answer":"24","hint":"In a proportional relationship, the ratio between two quantities stays constant.","explanation":"4 × 6 = 24.","kind":"numeric","difficulty":"easy"},{"id":"proportions-q2","prompt":"A recipe uses 2 cups of flour for 3 servings. How many cups for 9 servings?","answer":"6","hint":"In a proportional relationship, the ratio between two quantities stays constant.","explanation":"9 is 3 times 3, so use 3 × 2 = 6 cups.","kind":"numeric","difficulty":"easy"}]}]},{"id":"g6-decimal-division","title":"Decimal division","grades":[6],"lessons":[{"id":"g6-divide-decimals","title":"Dividing decimals","explanation":"Multiply both numbers in a division by the same power of ten to make the divisor a whole number. The quotient stays the same.","example":"4.8 ÷ 0.6 = 48 ÷ 6 = 8. Multiplying both numbers by 10 changes the size of each unit, but not how many groups fit.","questions":[{"id":"g6-divide-decimals-q1","prompt":"Calculate 3.6 ÷ 0.9.","answer":"4","hint":"Multiply both numbers by 10, then divide 36 by 9.","explanation":"3.6 ÷ 0.9 = 36 ÷ 9 = 4.","kind":"numeric","difficulty":"easy"},{"id":"g6-divide-decimals-q2","prompt":"Calculate 5.25 ÷ 0.5.","answer":"10.5","hint":"Multiply both numbers by 10: 52.5 ÷ 5.","explanation":"52.5 ÷ 5 = 10.5. Check: 10.5 × 0.5 = 5.25.","kind":"numeric","difficulty":"medium"},{"id":"g6-divide-decimals-q3","prompt":"A 2.4-liter bottle fills cups holding 0.15 liter each. How many cups can it fill?","answer":"16","hint":"Multiply both amounts by 100 so the divisor becomes 15.","explanation":"2.4 ÷ 0.15 = 240 ÷ 15 = 16 cups.","kind":"numeric","difficulty":"medium"}]}],"requires":[],"x":0,"y":200},{"id":"g6-percentages","title":"Percentages","grades":[6],"lessons":[{"id":"g6-percent-amounts","title":"Finding a percent of an amount","explanation":"Percent means out of 100. To find a percent of an amount, write the percent as a fraction over 100 or a decimal, then multiply.","example":"25% of 60 = 25/100 × 60 = 15. Since 25% is one quarter, you can also divide 60 by 4.","questions":[{"id":"g6-percent-amounts-q1","prompt":"What is 10% of 80?","answer":"8","hint":"10% is one tenth. Divide 80 by 10.","explanation":"10/100 × 80 = 8.","kind":"numeric","difficulty":"easy"},{"id":"g6-percent-amounts-q2","prompt":"What is 35% of 60?","answer":"21","hint":"Write 35% as 0.35 and multiply by 60.","explanation":"0.35 × 60 = 21. You can also add 30% of 60 (18) and 5% of 60 (3).","kind":"numeric","difficulty":"medium"},{"id":"g6-percent-amounts-q3","prompt":"A class has 24 students. 75% brought a book. How many students brought a book?","answer":"18","hint":"75% is three quarters. Find one quarter of 24, then multiply by 3.","explanation":"24 ÷ 4 = 6, and 6 × 3 = 18 students.","kind":"numeric","difficulty":"medium"}]}],"requires":["ratios"],"x":260,"y":200},{"id":"path-g7-integer-products","title":"Multiply and divide signed numbers","grades":[7],"requires":[],"lessons":[{"id":"g7-integer-products","title":"Multiply and divide signed numbers","explanation":"A product or quotient of two numbers with the same sign is positive. With different signs, it is negative.","example":"(−3) × (−4) = 12, while (−3) × 4 = −12.","questions":[{"id":"g7-integer-products-q1","prompt":"What is (−4) × 6?","answer":"-24","hint":"The signs differ, so the result is negative.","explanation":"4 × 6 = 24, so (−4) × 6 = −24.","kind":"numeric","difficulty":"easy"},{"id":"g7-integer-products-q2","prompt":"What is (−7) × (−3)?","answer":"21","hint":"The signs match, so the result is positive.","explanation":"7 × 3 = 21, so the result is 21.","kind":"numeric","difficulty":"medium"},{"id":"g7-integer-products-q3","prompt":"What is (−36) ÷ 9?","answer":"-4","hint":"Divide the sizes, then decide the sign.","explanation":"36 ÷ 9 = 4. Different signs give −4.","kind":"numeric","difficulty":"medium"}]}],"x":520,"y":200},{"id":"path-g7-percent-change","title":"Percent increase and decrease","grades":[7],"requires":["path-g7-integer-products"],"lessons":[{"id":"g7-percent-change","title":"Percent increase and decrease","explanation":"Find the percent of the original amount, then add for an increase or subtract for a decrease.","example":"A $40 item discounted by 25% loses $10, so the sale price is $30.","questions":[{"id":"g7-percent-change-q1","prompt":"A $50 bag is discounted by 20%. What is the sale price in dollars?","answer":"40","hint":"Find 20% of 50, then subtract the discount.","explanation":"0.20 × 50 = 10. The sale price is 50 − 10 = 40 dollars.","kind":"numeric","difficulty":"easy"},{"id":"g7-percent-change-q2","prompt":"A club has 80 members and grows by 15%. How many members does it have now?","answer":"92","hint":"Find 15% of 80 and add it to 80.","explanation":"0.15 × 80 = 12, and 80 + 12 = 92.","kind":"numeric","difficulty":"medium"},{"id":"g7-percent-change-q3","prompt":"A plant grows from 20 cm to 25 cm. What is its percent increase? Enter the percent number only.","answer":"25","hint":"Divide the increase by the original height, then multiply by 100.","explanation":"The increase is 5 cm. 5 ÷ 20 × 100 = 25%.","kind":"numeric","difficulty":"medium"}]}],"x":0,"y":400}],"planned":false}') on conflict(id) do update set content=excluded.content;
insert into public.units values ('ratios','pre-algebra','{"id":"ratios","title":"Ratios and unit rates","grades":[6],"requires":[],"x":0,"y":0,"lessons":[{"id":"ratios-practice","title":"Ratios and unit rates","explanation":"A unit rate tells you the amount for one. Divide the total by the number of units.","example":"12 dollars for 3 books means 4 dollars per book.","questions":[{"id":"ratios-q1","prompt":"Four notebooks cost $12. What is the cost of one notebook?","answer":"3","hint":"A unit rate tells you the amount for one. Divide the total by the number of units.","explanation":"12 ÷ 4 = 3 dollars per notebook.","kind":"numeric","difficulty":"easy"},{"id":"ratios-q2","prompt":"A cyclist travels 30 miles in 2 hours. What is the average speed in miles per hour?","answer":"15","hint":"A unit rate tells you the amount for one. Divide the total by the number of units.","explanation":"30 ÷ 2 = 15 miles per hour.","kind":"numeric","difficulty":"easy"}]},{"id":"g6-equivalent-ratios","title":"Building equivalent ratios","explanation":"Equivalent ratios describe the same relationship. Multiply or divide both quantities by the same nonzero number.","example":"A mix has 2 cups of juice for 3 cups of water. Doubling both gives 4 cups of juice for 6 cups of water: 2:3 = 4:6.","questions":[{"id":"g6-equivalent-ratios-q1","prompt":"A recipe uses 2 cups of oats for 3 cups of milk. How many cups of milk go with 6 cups of oats?","answer":"9","hint":"The oats increased from 2 to 6. Use that same multiplier for the milk.","explanation":"6 ÷ 2 = 3, so multiply the milk by 3: 3 × 3 = 9 cups.","kind":"numeric","difficulty":"easy"},{"id":"g6-equivalent-ratios-q2","prompt":"The ratio of blue beads to red beads is 3:5. If there are 20 red beads, how many blue beads are there?","answer":"12","hint":"Find how many times 5 fits into 20, then scale the 3 blue beads.","explanation":"20 ÷ 5 = 4, so there are 3 × 4 = 12 blue beads.","kind":"numeric","difficulty":"medium"},{"id":"g6-equivalent-ratios-q3","prompt":"Four notebooks cost $6 in total. At the same price per notebook, how many dollars do 10 notebooks cost?","answer":"15","hint":"Find the price of one notebook, then multiply by 10.","explanation":"$6 ÷ 4 = $1.50 each. Ten cost 10 × $1.50 = $15.","kind":"numeric","difficulty":"medium"}]}]}') on conflict(id) do update set content=excluded.content;
