insert into public.lessons values ('g7-integer-products','path-g7-integer-products','{"id":"g7-integer-products","title":"Multiply and divide signed numbers","explanation":"A product or quotient of two numbers with the same sign is positive. With different signs, it is negative.","example":"(−3) × (−4) = 12, while (−3) × 4 = −12.","questions":[{"id":"g7-integer-products-q1","prompt":"What is (−4) × 6?","answer":"-24","hint":"The signs differ, so the result is negative.","explanation":"4 × 6 = 24, so (−4) × 6 = −24.","kind":"numeric","difficulty":"easy"},{"id":"g7-integer-products-q2","prompt":"What is (−7) × (−3)?","answer":"21","hint":"The signs match, so the result is positive.","explanation":"7 × 3 = 21, so the result is 21.","kind":"numeric","difficulty":"medium"},{"id":"g7-integer-products-q3","prompt":"What is (−36) ÷ 9?","answer":"-4","hint":"Divide the sizes, then decide the sign.","explanation":"36 ÷ 9 = 4. Different signs give −4.","kind":"numeric","difficulty":"medium"}]}') on conflict(id) do update set content=excluded.content;
