insert into public.questions values ('g7-integer-products-q2','g7-integer-products','numeric','21','{"id":"g7-integer-products-q2","prompt":"What is (−7) × (−3)?","answer":"21","hint":"The signs match, so the result is positive.","explanation":"7 × 3 = 21, so the result is 21.","kind":"numeric","difficulty":"medium"}') on conflict(id) do update set answer=excluded.answer,content=excluded.content;
insert into public.questions values ('g7-integer-products-q3','g7-integer-products','numeric','-4','{"id":"g7-integer-products-q3","prompt":"What is (−36) ÷ 9?","answer":"-4","hint":"Divide the sizes, then decide the sign.","explanation":"36 ÷ 9 = 4. Different signs give −4.","kind":"numeric","difficulty":"medium"}') on conflict(id) do update set answer=excluded.answer,content=excluded.content;
insert into public.units values ('path-g7-percent-change','pre-algebra','{"id":"path-g7-percent-change","title":"Percent increase and decrease","grades":[7],"requires":["path-g7-integer-products"],"lessons":[{"id":"g7-percent-change","title":"Percent increase and decrease","explanation":"Find the percent of the original amount, then add for an increase or subtract for a decrease.","example":"A $40 item discounted by 25% loses $10, so the sale price is $30.","questions":[{"id":"g7-percent-change-q1","prompt":"A $50 bag is discounted by 20%. What is the sale price in dollars?","answer":"40","hint":"Find 20% of 50, then subtract the discount.","explanation":"0.20 × 50 = 10. The sale price is 50 − 10 = 40 dollars.","kind":"numeric","difficulty":"easy"},{"id":"g7-percent-change-q2","prompt":"A club has 80 members and grows by 15%. How many members does it have now?","answer":"92","hint":"Find 15% of 80 and add it to 80.","explanation":"0.15 × 80 = 12, and 80 + 12 = 92.","kind":"numeric","difficulty":"medium"},{"id":"g7-percent-change-q3","prompt":"A plant grows from 20 cm to 25 cm. What is its percent increase? Enter the percent number only.","answer":"25","hint":"Divide the increase by the original height, then multiply by 100.","explanation":"The increase is 5 cm. 5 ÷ 20 × 100 = 25%.","kind":"numeric","difficulty":"medium"}]}],"x":0,"y":400}') on conflict(id) do update set content=excluded.content;
insert into public.lessons values ('g7-percent-change','path-g7-percent-change','{"id":"g7-percent-change","title":"Percent increase and decrease","explanation":"Find the percent of the original amount, then add for an increase or subtract for a decrease.","example":"A $40 item discounted by 25% loses $10, so the sale price is $30.","questions":[{"id":"g7-percent-change-q1","prompt":"A $50 bag is discounted by 20%. What is the sale price in dollars?","answer":"40","hint":"Find 20% of 50, then subtract the discount.","explanation":"0.20 × 50 = 10. The sale price is 50 − 10 = 40 dollars.","kind":"numeric","difficulty":"easy"},{"id":"g7-percent-change-q2","prompt":"A club has 80 members and grows by 15%. How many members does it have now?","answer":"92","hint":"Find 15% of 80 and add it to 80.","explanation":"0.15 × 80 = 12, and 80 + 12 = 92.","kind":"numeric","difficulty":"medium"},{"id":"g7-percent-change-q3","prompt":"A plant grows from 20 cm to 25 cm. What is its percent increase? Enter the percent number only.","answer":"25","hint":"Divide the increase by the original height, then multiply by 100.","explanation":"The increase is 5 cm. 5 ÷ 20 × 100 = 25%.","kind":"numeric","difficulty":"medium"}]}') on conflict(id) do update set content=excluded.content;
