insert into public.units values ('path-g10-pythagoras','geometry','{"id":"path-g10-pythagoras","title":"The Pythagorean theorem","grades":[10],"requires":[],"lessons":[{"id":"g10-pythagoras","title":"The Pythagorean theorem","explanation":"For a right triangle, a² + b² = c², where c is the hypotenuse opposite the right angle.","example":"Legs 3 and 4 give c² = 9 + 16 = 25, so c = 5.","questions":[{"id":"g10-pythagoras-q1","prompt":"A right triangle has legs 6 cm and 8 cm. What is its hypotenuse in centimeters?","answer":"10","hint":"Square each leg, add, then take the positive square root.","explanation":"6² + 8² = 100, so c = 10 centimeters.","kind":"numeric","difficulty":"easy"},{"id":"g10-pythagoras-q2","prompt":"A right triangle has hypotenuse 13 m and one leg 5 m. What is its other leg in meters?","answer":"12","hint":"Subtract 5² from 13², then take the positive square root.","explanation":"169 − 25 = 144, so the other leg is 12 meters.","kind":"numeric","difficulty":"medium"},{"id":"g10-pythagoras-q3","prompt":"A square has side length 5 units. What is the square of its diagonal length?","answer":"50","hint":"The diagonal makes a right triangle with two legs of length 5.","explanation":"d² = 5² + 5² = 50.","kind":"numeric","difficulty":"medium"}]}],"x":260,"y":200}') on conflict(id) do update set content=excluded.content;
