insert into public.units values ('path-g10-circles','geometry','{"id":"path-g10-circles","title":"Area and circumference of circles","grades":[10],"requires":["path-g10-pythagoras"],"lessons":[{"id":"g10-circles","title":"Area and circumference of circles","explanation":"For radius r, area = πr² and circumference = 2πr. The diameter is twice the radius. Use π = 3.14 in this lesson.","example":"A circle with radius 2 has area 3.14 × 2² = 12.56 square units.","questions":[{"id":"g10-circles-q1","prompt":"Using π = 3.14, find the area of a circle with radius 3 cm, in square centimeters.","answer":"28.26","hint":"Square the radius, then multiply by 3.14.","explanation":"3.14 × 3² = 3.14 × 9 = 28.26.","kind":"numeric","difficulty":"easy"},{"id":"g10-circles-q2","prompt":"Using π = 3.14, find the circumference of a circle with radius 5 m, in meters.","answer":"31.4","hint":"Multiply 2 × 3.14 × 5.","explanation":"The circumference is 31.4 meters.","kind":"numeric","difficulty":"medium"},{"id":"g10-circles-q3","prompt":"Using π = 3.14, find the area of a circle with diameter 8 cm, in square centimeters.","answer":"50.24","hint":"First halve the diameter to get the radius.","explanation":"r = 4. Area = 3.14 × 4² = 50.24 square centimeters.","kind":"numeric","difficulty":"medium"}]}],"x":520,"y":200}') on conflict(id) do update set content=excluded.content;
