insert into public.courses values ('algebra-ii','{"id":"algebra-ii","title":"Algebra II","subject":"Algebra II","grades":[11],"description":"Explore introductory algebra ii lessons.","units":[{"id":"exponent-rules","title":"Exponent rules","grades":[11],"requires":[],"x":0,"y":0,"lessons":[{"id":"exponent-rules-practice","title":"Exponent rules","explanation":"When multiplying powers with the same base, add the exponents.","example":"2³ × 2² = 2⁵ = 32.","questions":[{"id":"exponent-rules-q1","prompt":"Evaluate 3² × 3³.","answer":"243","hint":"When multiplying powers with the same base, add the exponents.","explanation":"3² × 3³ = 3⁵ = 243.","kind":"numeric","difficulty":"easy"},{"id":"exponent-rules-q2","prompt":"Evaluate (2³)².","answer":"64","hint":"When multiplying powers with the same base, add the exponents.","explanation":"Multiply the exponents: 2⁶ = 64.","kind":"numeric","difficulty":"easy"}]}]},{"id":"path-g11-quadratic-vertex","title":"Locate a quadratic vertex","grades":[11],"requires":[],"lessons":[{"id":"g11-quadratic-vertex","title":"Locate a quadratic vertex","explanation":"For y = ax² + bx + c, the vertex''s x-coordinate is −b/(2a). Substitute that x to find its y-coordinate.","example":"For y = x² − 6x + 5, the vertex has x = 6/2 = 3, and y = 9 − 18 + 5 = −4.","questions":[{"id":"g11-quadratic-vertex-q1","prompt":"Find the x-coordinate of the vertex of y = x² − 8x + 3.","answer":"4","hint":"Here a = 1 and b = −8. Use −b/(2a).","explanation":"x = 8 ÷ 2 = 4.","kind":"numeric","difficulty":"easy"},{"id":"g11-quadratic-vertex-q2","prompt":"Find the x-coordinate of the vertex of y = 2x² + 12x + 1.","answer":"-3","hint":"Use a = 2 and b = 12.","explanation":"x = −12 ÷ (2 × 2) = −3.","kind":"numeric","difficulty":"medium"},{"id":"g11-quadratic-vertex-q3","prompt":"For y = x² − 4x + 7, find the vertex''s y-coordinate.","answer":"3","hint":"First find x = −b/(2a), then substitute.","explanation":"x = 2, so y = 4 − 8 + 7 = 3.","kind":"numeric","difficulty":"medium"}]}],"x":260,"y":0},{"id":"path-g11-sequences","title":"Arithmetic sequences","grades":[11],"requires":["path-g11-quadratic-vertex"],"lessons":[{"id":"g11-sequences","title":"Arithmetic sequences","explanation":"An arithmetic sequence adds the same difference each time. Its nth term is first term + (n − 1) × common difference.","example":"For 3, 7, 11, … the difference is 4. The fifth term is 3 + 4 × 4 = 19.","questions":[{"id":"g11-sequences-q1","prompt":"What is the next term: 5, 8, 11, __?","answer":"14","hint":"Find the common difference.","explanation":"The difference is 3. 11 + 3 = 14.","kind":"numeric","difficulty":"easy"},{"id":"g11-sequences-q2","prompt":"A sequence starts at 2 and adds 5 each time. What is its sixth term?","answer":"27","hint":"There are five jumps from the first term to the sixth.","explanation":"2 + (6 − 1) × 5 = 27.","kind":"numeric","difficulty":"medium"},{"id":"g11-sequences-q3","prompt":"A sequence starts at 30 and subtracts 4 each time. What is its fifth term?","answer":"14","hint":"Use four jumps of −4.","explanation":"30 + 4 × (−4) = 14.","kind":"numeric","difficulty":"medium"}]}],"x":520,"y":0}],"planned":false}') on conflict(id) do update set content=excluded.content;
