insert into public.courses values ('precalculus','{"id":"precalculus","title":"Precalculus","subject":"Precalculus","grades":[12],"description":"Explore introductory precalculus lessons.","units":[{"id":"function-composition","title":"Combining functions","grades":[12],"requires":[],"x":0,"y":0,"lessons":[{"id":"function-composition-practice","title":"Combining functions","explanation":"For f(g(x)), evaluate g first and use that output as the input to f.","example":"If f(x) = 2x and g(x) = x + 3, then f(g(4)) = f(7) = 14.","questions":[{"id":"function-composition-q1","prompt":"If f(x) = 3x + 1 and g(x) = x − 2, find f(g(5)).","answer":"10","hint":"For f(g(x)), evaluate g first and use that output as the input to f.","explanation":"g(5) = 3, then f(3) = 3 × 3 + 1 = 10.","kind":"numeric","difficulty":"easy"},{"id":"function-composition-q2","prompt":"For those same functions, find g(f(2)).","answer":"5","hint":"For f(g(x)), evaluate g first and use that output as the input to f.","explanation":"f(2) = 7, then g(7) = 7 − 2 = 5.","kind":"numeric","difficulty":"easy"}]}]},{"id":"right-triangle-trig","title":"Right-triangle trigonometry","grades":[12],"requires":["function-composition"],"x":260,"y":0,"lessons":[{"id":"right-triangle-trig-practice","title":"Right-triangle trigonometry","explanation":"For an acute angle in a right triangle, sine equals opposite divided by hypotenuse.","example":"If the opposite side is 3 and the hypotenuse is 5, sine is 3/5 = 0.6.","questions":[{"id":"right-triangle-trig-q1","prompt":"The side opposite an angle is 5 and the hypotenuse is 13. Enter the sine as a fraction.","answer":"5/13","hint":"For an acute angle in a right triangle, sine equals opposite divided by hypotenuse.","explanation":"Sine is opposite divided by hypotenuse: 5/13.","kind":"numeric","difficulty":"easy"},{"id":"right-triangle-trig-q2","prompt":"An angle has sine 0.6 and the hypotenuse is 10. Find the opposite side.","answer":"6","hint":"For an acute angle in a right triangle, sine equals opposite divided by hypotenuse.","explanation":"Opposite = sine × hypotenuse = 0.6 × 10 = 6.","kind":"numeric","difficulty":"easy"}]}]},{"id":"path-g12-exponential-growth","title":"Exponential growth","grades":[12],"requires":[],"lessons":[{"id":"g12-exponential-growth","title":"Exponential growth","explanation":"In exponential growth, an amount is multiplied by the same factor each step. After n steps, multiply the initial amount by factorⁿ.","example":"Starting with 5 and doubling each step gives 5 × 2³ = 40 after three steps.","questions":[{"id":"g12-exponential-growth-q1","prompt":"A quantity starts at 3 and triples each step. What is it after 2 steps?","answer":"27","hint":"Multiply 3 by 3².","explanation":"3 × 3² = 3 × 9 = 27.","kind":"numeric","difficulty":"easy"},{"id":"g12-exponential-growth-q2","prompt":"An account starts at $100 and grows by 10% once per year. How many dollars after 2 years?","answer":"121","hint":"A 10% increase uses a factor of 1.10 each year.","explanation":"100 × 1.1² = 121 dollars.","kind":"numeric","difficulty":"medium"},{"id":"g12-exponential-growth-q3","prompt":"A substance starts at 80 grams and halves each hour. How many grams after 3 hours?","answer":"10","hint":"Use a factor of 1/2 three times.","explanation":"80 × (1/2)³ = 80 ÷ 8 = 10 grams.","kind":"numeric","difficulty":"medium"}]}],"x":520,"y":0},{"id":"path-g12-logarithms","title":"Logarithms as missing exponents","grades":[12],"requires":["path-g12-exponential-growth"],"lessons":[{"id":"g12-logarithms","title":"Logarithms as missing exponents","explanation":"A logarithm asks for an exponent: log base b of a = x means bˣ = a. The base is positive and not 1, and a is positive.","example":"log base 2 of 8 = 3 because 2³ = 8.","questions":[{"id":"g12-logarithms-q1","prompt":"What is log base 2 of 32?","answer":"5","hint":"2 raised to what power gives 32?","explanation":"2⁵ = 32, so the logarithm is 5.","kind":"numeric","difficulty":"easy"},{"id":"g12-logarithms-q2","prompt":"What is log base 10 of 0.01?","answer":"-2","hint":"0.01 is one hundredth. Think of a negative power of 10.","explanation":"10⁻² = 1/100 = 0.01, so the logarithm is −2.","kind":"numeric","difficulty":"medium"},{"id":"g12-logarithms-q3","prompt":"What is log base 3 of 1?","answer":"0","hint":"Any nonzero base raised to this exponent is 1.","explanation":"3⁰ = 1, so the logarithm is 0.","kind":"numeric","difficulty":"medium"}]}],"x":0,"y":200}],"planned":false}') on conflict(id) do update set content=excluded.content;
insert into public.units values ('function-composition','precalculus','{"id":"function-composition","title":"Combining functions","grades":[12],"requires":[],"x":0,"y":0,"lessons":[{"id":"function-composition-practice","title":"Combining functions","explanation":"For f(g(x)), evaluate g first and use that output as the input to f.","example":"If f(x) = 2x and g(x) = x + 3, then f(g(4)) = f(7) = 14.","questions":[{"id":"function-composition-q1","prompt":"If f(x) = 3x + 1 and g(x) = x − 2, find f(g(5)).","answer":"10","hint":"For f(g(x)), evaluate g first and use that output as the input to f.","explanation":"g(5) = 3, then f(3) = 3 × 3 + 1 = 10.","kind":"numeric","difficulty":"easy"},{"id":"function-composition-q2","prompt":"For those same functions, find g(f(2)).","answer":"5","hint":"For f(g(x)), evaluate g first and use that output as the input to f.","explanation":"f(2) = 7, then g(7) = 7 − 2 = 5.","kind":"numeric","difficulty":"easy"}]}]}') on conflict(id) do update set content=excluded.content;
