insert into public.courses values ('statistics','{"id":"statistics","title":"Statistics","subject":"Statistics","grades":[6],"description":"Explore introductory statistics lessons.","units":[{"id":"g6-data-centers","title":"Understanding data","grades":[6],"lessons":[{"id":"g6-mean-median","title":"Mean and median","explanation":"The mean is the sum of the values divided by how many values there are. The median is the middle value after sorting. With an even number of values, average the two middle values.","example":"For 2, 3, 7, the mean is (2 + 3 + 7) ÷ 3 = 4, and the median is 3. Mean and median can be different.","questions":[{"id":"g6-mean-median-q1","prompt":"Find the mean of 4, 6 and 8.","answer":"6","hint":"Add the three values and divide by 3.","explanation":"(4 + 6 + 8) ÷ 3 = 18 ÷ 3 = 6.","kind":"numeric","difficulty":"easy"},{"id":"g6-mean-median-q2","prompt":"Find the median of 9, 2, 7, 4 and 3.","answer":"4","hint":"Sort from smallest to largest, then find the middle value.","explanation":"The sorted values are 2, 3, 4, 7, 9. The middle value is 4.","kind":"numeric","difficulty":"medium"},{"id":"g6-mean-median-q3","prompt":"Find the median of 2, 5, 8 and 11.","answer":"6.5","hint":"There are two middle values, 5 and 8. Find their mean.","explanation":"(5 + 8) ÷ 2 = 13 ÷ 2 = 6.5.","kind":"numeric","difficulty":"medium"}]}],"requires":[],"x":0,"y":0}],"planned":false}') on conflict(id) do update set content=excluded.content;
