insert into public.questions values ('sat1','sat-algebra','numeric','7','{"id":"sat1","prompt":"A club costs $12 plus $4 per visit. If the total is $40, how many visits?","answer":"7","hint":"Subtract the fixed fee first.","explanation":"40 − 12 = 28, then 28 ÷ 4 = 7.","kind":"numeric","difficulty":"easy"}') on conflict(id) do update set answer=excluded.answer,content=excluded.content;
insert into public.questions values ('sat2','sat-algebra','numeric','9','{"id":"sat2","prompt":"If 5x − 7 = 3x + 11, find x.","answer":"9","hint":"Collect x terms on one side.","explanation":"2x = 18, so x = 9.","kind":"numeric","difficulty":"medium"}') on conflict(id) do update set answer=excluded.answer,content=excluded.content;
insert into public.lessons values ('sat-advanced','sat','{"id":"sat-advanced","title":"Advanced Math","explanation":"Factor a quadratic to find its roots.","example":"x² − 5x + 6 = (x − 2)(x − 3).","questions":[{"id":"sat3","prompt":"Find the larger root of x² − 7x + 12 = 0.","answer":"4","hint":"Find two numbers with product 12 and sum 7.","explanation":"(x − 3)(x − 4) = 0. The larger root is 4.","kind":"numeric","difficulty":"hard"}]}') on conflict(id) do update set content=excluded.content;
insert into public.questions values ('sat3','sat-advanced','numeric','4','{"id":"sat3","prompt":"Find the larger root of x² − 7x + 12 = 0.","answer":"4","hint":"Find two numbers with product 12 and sum 7.","explanation":"(x − 3)(x − 4) = 0. The larger root is 4.","kind":"numeric","difficulty":"hard"}') on conflict(id) do update set answer=excluded.answer,content=excluded.content;
insert into public.lessons values ('sat-data','sat','{"id":"sat-data","title":"Problem-Solving and Data Analysis","explanation":"A percentage increase multiplies the original quantity by 1 plus the rate.","example":"A 20% increase on 50 gives 50 × 1.2 = 60.","questions":[{"id":"sat4","prompt":"A price rises from $80 to $100. What is the percent increase?","answer":"25","hint":"Divide the increase by the original price.","explanation":"(100 − 80) ÷ 80 × 100 = 25%.","kind":"numeric","difficulty":"medium"}]}') on conflict(id) do update set content=excluded.content;
insert into public.questions values ('sat4','sat-data','numeric','25','{"id":"sat4","prompt":"A price rises from $80 to $100. What is the percent increase?","answer":"25","hint":"Divide the increase by the original price.","explanation":"(100 − 80) ÷ 80 × 100 = 25%.","kind":"numeric","difficulty":"medium"}') on conflict(id) do update set answer=excluded.answer,content=excluded.content;
insert into public.lessons values ('sat-geometry','sat','{"id":"sat-geometry","title":"Geometry and Trigonometry","explanation":"For a right triangle, a² + b² = c² where c is the hypotenuse.","example":"Legs of 3 and 4 give c = √25 = 5.","questions":[{"id":"sat5","prompt":"A right triangle has legs 5 and 12. Find its hypotenuse.","answer":"13","hint":"Square each leg, then add.","explanation":"25 + 144 = 169; √169 = 13.","kind":"numeric","difficulty":"medium"}]}') on conflict(id) do update set content=excluded.content;
insert into public.questions values ('sat5','sat-geometry','numeric','13','{"id":"sat5","prompt":"A right triangle has legs 5 and 12. Find its hypotenuse.","answer":"13","hint":"Square each leg, then add.","explanation":"25 + 144 = 169; √169 = 13.","kind":"numeric","difficulty":"medium"}') on conflict(id) do update set answer=excluded.answer,content=excluded.content;
